INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-act-2023-section-2-clauses-a-to-g', 'dpdp-act-2023', 'The Digital Personal Data Protection Act, 2023', 'Section 2', 'Section 2 — Definitions (Appellate Tribunal to Consent Manager)',
    '2. In this Act, unless the context otherwise requires,—
(a) “Appellate Tribunal” means the Telecom Disputes Settlement and  Appellate
Tribunal established under section 14 of the Telecom Regulatory Authority of India
Act, 1997;
(b) “automated” means any digital process capable of operating automatically
in response to instructions given or otherwise for the purpose of processing data;
(c) “Board” means the Data Protection Board of India established by the Central
Government under section 18;
(d) “certain legitimate uses” means the uses referred to in section 7;
(e) “Chairperson” means the Chairperson of the Board;
(f) “child” means an individual who has not completed the age of eighteen
years;
(g) “Consent Manager” means a person registered with the Board, who acts as
a single point of contact to enable a Data Principal to give, manage, review and
withdraw her consent through an accessible, transparent and interoperable platform;', 'IN_FORCE', '2025-11-13', 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf', '', '[-0.066434,-0.010079,-0.083745,-0.035082,-0.047536,0.016582,0.082223,0.053177,-0.029088,0.051297,0.044858,-0.015434,0.052907,0.029679,-0.019458,0.018347,0.062855,-0.111490,-0.023672,-0.005931,0.064279,0.051463,-0.053582,-0.053003,-0.041827,-0.021709,-0.030342,-0.064102,0.030474,0.030070,0.027814,0.074735,0.052995,0.056064,-0.019172,-0.050696,-0.025847,0.027333,0.003090,-0.070590,0.025611,-0.043794,-0.033677,-0.007651,0.035790,0.055799,-0.024450,-0.016919,-0.144101,-0.041243,-0.091815,-0.038626,-0.014135,0.100021,-0.072000,-0.061240,0.051694,-0.052297,0.017410,0.003897,-0.028976,0.040488,-0.033578,0.052882,0.021955,0.001418,-0.023819,-0.055141,0.061152,0.001605,-0.034834,-0.045847,-0.030788,0.058016,-0.032873,-0.075843,-0.094936,0.072515,0.093320,-0.104157,-0.052853,0.042291,0.053311,0.016133,-0.083480,0.000796,-0.012927,0.011326,0.040456,-0.003653,0.097733,0.064506,0.046478,0.048885,-0.072141,-0.067504,0.010566,-0.052406,0.040193,0.004016,-0.002578,0.090822,-0.088851,0.040624,-0.122850,-0.020597,-0.000839,-0.009768,0.025815,-0.011078,-0.089752,0.021373,-0.041668,-0.065842,-0.049790,0.005955,-0.054701,0.054495,0.069252,-0.026218,-0.039463,0.020248,-0.015634,-0.013355,0.008497,-0.041909,-0.018871,-0.000000,-0.049064,0.004226,-0.081110,0.006447,0.026538,0.026572,0.026393,0.001466,-0.002104,0.069139,-0.004283,-0.029899,0.009301,-0.037405,0.039181,0.038538,0.008636,0.008667,0.005992,0.037443,0.049377,0.063598,0.073355,0.045781,0.060781,-0.034180,-0.016147,0.037641,0.080411,0.013687,-0.002445,-0.071504,-0.027709,0.045146,0.052732,0.078013,-0.004879,-0.049294,-0.013726,0.024273,-0.099536,-0.018301,0.006150,-0.014272,-0.002765,-0.015382,0.025690,0.021926,0.021827,0.115155,0.000583,0.010401,0.045446,-0.060250,0.019652,0.035141,-0.013714,-0.000693,-0.006455,-0.023547,0.08919