INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-act-2023-section-2-clauses-h-to-n', 'dpdp-act-2023', 'The Digital Personal Data Protection Act, 2023', 'Section 2', 'Section 2 — Definitions (Data to Digital Personal Data)',
    '2. In this Act, unless the context otherwise requires,—
(h) “data” means a representation of information, facts, concepts, opinions or
instructions in a manner suitable for communication, interpretation or processing by
human beings or by automated means;
(i) “Data Fiduciary” means any person who alone or in conjunction with other
persons determines the purpose and means of processing of personal data;
(j) “Data Principal” means the individual to whom the personal data relates and
where such individual is—
(i) a child, includes the parents or lawful guardian of such a child;
(ii) a person with disability, includes her lawful guardian, acting on her
behalf;
(k) “Data Processor” means any person who processes personal data on behalf
of a Data Fiduciary;
(l) “Data Protection Officer” means an individual appointed by the Significant
Data Fiduciary under clause (a) of sub-section (2) of section 10;
(m) “digital office” means an office that adopts an online mechanism wherein
the proceedings, from receipt of intimation or complaint or reference or directions or
appeal, as the case may be, to the disposal thereof, are conducted in online or digital
mode;
(n) “digital personal data” means personal data in digital form;', 'IN_FORCE', '2025-11-13', 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf', '', '[-0.090548,0.037212,-0.048812,-0.022199,-0.047268,-0.021976,0.084316,0.049280,-0.037020,0.028552,0.079569,0.018646,0.059146,-0.043946,-0.063460,0.041683,0.066312,-0.046620,-0.065094,0.066404,0.098882,0.029297,-0.044955,0.002264,0.003710,0.079926,-0.028632,-0.061593,0.007599,-0.005148,0.000480,-0.013113,0.051012,0.079161,0.005094,0.000277,0.066027,0.029856,-0.049634,-0.021898,-0.023245,-0.059414,-0.029898,-0.035884,-0.006255,-0.002122,0.029075,-0.028734,-0.106942,0.025396,-0.143071,0.014200,-0.001106,0.195242,-0.064785,-0.054944,0.068554,-0.015966,-0.024540,0.033461,-0.033467,-0.016287,0.019344,0.025375,0.058848,0.028853,-0.006086,-0.074099,0.010779,-0.026909,-0.031557,-0.018133,-0.032350,0.089264,0.037929,-0.120252,-0.097688,0.017811,0.069552,-0.074069,0.049895,0.100403,-0.001539,0.036556,-0.038479,-0.047837,-0.034021,-0.004572,-0.013333,-0.034345,0.009041,0.024334,0.005349,0.045437,0.001873,-0.056478,-0.002753,-0.049057,0.062939,-0.025158,-0.016024,0.066694,-0.028768,0.036605,-0.059640,-0.097541,-0.007821,-0.010733,-0.048753,0.001672,-0.050276,0.011175,-0.106393,-0.064592,0.003670,-0.013452,-0.117069,0.078019,-0.006242,-0.027499,0.013878,-0.007814,0.004576,-0.016884,0.044697,-0.094728,-0.062812,0.000000,0.002007,0.046983,-0.031255,-0.020457,0.027593,0.016225,-0.028686,-0.000795,-0.019331,0.043655,-0.003238,0.056943,0.028760,0.012589,0.017148,0.040964,-0.003128,0.057952,0.055755,0.048714,0.125111,0.066409,0.027534,0.078024,0.073335,-0.013414,-0.036587,0.034617,0.030585,0.012509,-0.060083,-0.054766,0.051092,-0.037636,0.105485,0.010502,-0.001115,-0.059207,-0.006881,0.017094,0.023292,0.004553,0.063810,0.003856,-0.063119,0.008491,0.034624,-0.008332,0.007394,0.082181,0.027446,-0.011158,0.010510,-0.040032,-0.003588,0.009110,-0.045611,-0.045764,-0.001661,-0.032513,0.014151,-0.020158,0.00043