) VALUES (
    'dpdp-act-2023-section-2-clauses-o-to-s', 'dpdp-act-2023', 'The Digital Personal Data Protection Act, 2023', 'Section 2', 'Section 2 — Definitions (Gain to Person)',
    '2. In this Act, unless the context otherwise requires,—
(o) “gain” means—
(i) a gain in property or supply of services, whether temporary or
permanent; or
(ii) an opportunity to earn remuneration or greater remuneration or to
gain a financial advantage otherwise than by way of legitimate remuneration;
(p) “loss” means—
(i) a loss in property or interruption in supply of services, whether
temporary or permanent; or
(ii) a loss of opportunity to earn remuneration or greater remuneration or
to gain a financial advantage otherwise than by way of legitimate remuneration;
Definitions.
24 of 1997.

(q) “Member” means a Member of the Board and includes the Chairperson;
(r) “notification” means a notification published in the Official Gazette and the
expressions “notify” and “notified” shall be construed accordingly;
(s) “person” includes—
(i) an individual;
(ii) a Hindu undivided family;
(iii) a company;
(iv) a firm;
(v) an association of persons or a body of individuals, whether
incorporated or not;
(vi) the State; and
(vii) every artificial juristic person, not falling within any of the preceding
sub-clauses;', 'IN_FORCE', '2025-11-13', 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf', '', '[-0.074320,0.039831,-0.035049,-0.026052,-0.039673,0.037269,0.143872,-0.052659,0.057085,-0.021684,0.053189,-0.059357,0.080974,-0.006564,-0.032187,0.002789,0.053081,0.031093,-0.038415,0.053361,0.015653,0.006477,-0.067715,0.063636,0.022633,-0.130271,-0.007515,-0.044194,0.072785,-0.003991,0.039703,0.015771,-0.007327,0.020726,-0.002401,0.011608,0.051033,-0.021154,-0.030072,-0.034525,0.027256,-0.058043,-0.042359,-0.014704,-0.003279,0.036904,0.012487,-0.022445,-0.099810,0.024519,0.003081,-0.014495,0.020427,0.111305,-0.014698,0.016685,-0.011591,-0.056693,-0.036999,-0.010501,0.027759,0.036097,0.009310,0.014393,0.033270,-0.070699,-0.048364,-0.011461,-0.080900,0.002469,0.027792,-0.056623,0.011679,-0.003576,-0.071966,-0.064226,0.051521,0.083380,-0.006299,-0.048150,-0.051337,0.054799,-0.033147,-0.057231,-0.040443,-0.031362,0.034348,-0.011744,0.114742,0.080289,-0.001889,0.036585,0.059861,-0.003352,0.003462,-0.029229,-0.011570,-0.033531,-0.008514,0.098437,-0.038379,0.025415,-0.051757,-0.038829,-0.077077,-0.022191,-0.129888,0.003115,0.028792,-0.002603,-0.089874,-0.023806,0.003624,-0.045878,-0.013139,0.128258,-0.042303,0.076160,0.037293,-0.122970,0.000533,0.045874,0.011015,-0.003396,-0.015033,-0.056374,-0.048591,-0.000000,-0.067634,0.000328,-0.002965,-0.001694,0.001793,-0.049839,0.001121,-0.052781,-0.010555,-0.030213,0.029740,0.015905,0.090859,0.000603,0.042295,-0.020882,-0.015472,-0.010007,0.100542,-0.023395,0.038980,0.058677,0.001660,0.078283,0.038548,-0.080701,-0.055082,0.028960,-0.040621,0.010024,0.101990,0.004503,-0.003708,-0.058157,0.083128,0.028982,-0.017614,-0.006907,-0.014770,-0.094325,-0.046416,-0.024346,0.041343,-0.020800,-0.009497,-0.009239,0.090594,0.036393,-0.014305,0.078990,0.057290,-0.027871,0.062344,-0.024041,-0.033084,-0.041135,-0.077842,0.082563,-0.058546,-0.042583,-0.011176,-0.063628,-0.018796,0.045262,-0.122500,-0.015323,0.018470,