INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-act-2023-section-2-clauses-t-to-zb', 'dpdp-act-2023', 'The Digital Personal Data Protection Act, 2023', 'Section 2', 'Section 2 — Definitions (Personal Data, Breach, Processing to State)',
    '2. In this Act, unless the context otherwise requires,—
(t) “personal data” means any data about an individual who is identifiable by or
in relation to such data;
(u) “personal data breach” means any unauthorised processing of personal
data or accidental disclosure, acquisition, sharing, use, alteration, destruction or loss
of access to personal data, that compromises the confidentiality, integrity or availability
of personal data;
(v) “prescribed” means prescribed by rules made under this Act;
(w) “proceeding” means any action taken by the Board under the provisions of
this Act;
(x) “processing” in relation to personal data, means a wholly or partly automated
operation or set of operations performed on digital personal data, and includes
operations such as collection, recording, organisation, structuring, storage, adaptation,
retrieval, use, alignment or combination, indexing, sharing, disclosure by transmission,
dissemination or otherwise making available, restriction, erasure or destruction;
(y) “she” in relation to an individual includes the reference to such individual
irrespective of gender;
(z) “Significant Data Fiduciary” means any Data Fiduciary or class of Data
Fiduciaries as may be notified by the Central Government under section 10;
(za) “specified purpose” means the purpose mentioned in the notice given by
the Data Fiduciary to the Data Principal in accordance with the provisions of this Act
and the rules made thereunder; and
(zb) “State” means the State as defined under article 12 of the Constitution.', 'IN_FORCE', '2025-11-13', 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf', '', '[-0.059288,0.040542,-0.037805,-0.025952,-0.032012,-0.026739,0.105589,0.006792,-0.018869,0.040072,0.075854,0.005383,0.054451,-0.031247,-0.040311,-0.017942,0.056988,-0.073048,-0.085677,0.112154,0.086002,0.034093,-0.028011,-0.014324,-0.061653,0.010478,-0.021479,-0.074016,0.001268,-0.015014,0.044113,0.054589,0.058053,0.105718,0.033845,-0.017917,0.002716,-0.007440,-0.025780,-0.042882,-0.038046,-0.094307,-0.046613,0.033400,0.021414,0.058245,0.025935,-0.000990,-0.093356,0.065554,-0.141401,0.009751,-0.033361,0.177297,-0.038918,-0.046051,0.015826,-0.044659,-0.023525,-0.022688,-0.010027,-0.003941,0.013468,0.028181,0.048999,0.012914,-0.000903,-0.057819,0.059517,0.038436,-0.024921,-0.034511,-0.094689,0.089132,0.004116,-0.116341,-0.031486,0.001714,0.015069,-0.064597,-0.005499,0.068565,0.039965,-0.009221,-0.047403,-0.077660,-0.025722,0.009796,0.020076,0.019467,-0.065708,-0.006900,0.039412,0.013588,0.026697,-0.048402,-0.010417,-0.035994,0.070375,-0.009496,-0.020811,0.076296,-0.068367,-0.001593,-0.085615,-0.052849,-0.032970,-0.021213,-0.082694,0.028051,-0.046057,-0.018342,-0.069087,-0.134303,0.072600,0.032497,-0.088827,0.092371,-0.020447,-0.021788,-0.002178,0.006103,0.010728,-0.003959,-0.056237,-0.098566,-0.022813,0.000000,-0.034882,-0.029406,-0.081243,-0.006071,0.000369,0.038155,-0.025006,-0.033575,0.014463,0.059211,0.020564,0.055705,-0.002885,0.021958,0.039725,0.076611,0.035007,0.055378,0.041448,0.062432,0.149209,0.008816,-0.005403,0.053500,0.056641,-0.039138,-0.013464,0.018846,-0.036694,0.000867,-0.027057,-0.020523,0.074699,-0.002854,0.117128,0.014453,-0.013987,-0.044726,0.005393,0.018427,-0.021111,0.008752,0.026489,-0.000606,-0.068875,-0.033180,0.021077,0.048729,-0.026044,0.035041,0.071434,0.020708,0.013661,-0.048049,-0.058414,0.037295,-0.011088,-0.054373,-0.027342,0.002556,0.010438