INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-act-2023-section-5', 'dpdp-act-2023', 'The Digital Personal Data Protection Act, 2023', 'Section 5', 'Section 5 — Notice given by Data Fiduciary',
    '5. (1) Every request made to a Data Principal under section 6 for consent shall be
accompanied or preceded by a notice given by the Data Fiduciary to the Data Principal,
informing her,—
  (i) the personal data and the purpose for which the same is proposed to be
processed;
  (ii) the manner in which she may exercise her rights under sub-section (4) of
section 6 and section 13; and
 (iii) the manner in which the Data Principal may make a complaint to the Board,
in such manner and as may be prescribed.
Illustration.
X, an individual, opens a bank account using the mobile app or website of Y, a bank.
To complete the Know-Your-Customer requirements under law for opening of bank account,
X opts for processing of her personal data by Y in a live, video-based customer identification
process. Y shall accompany or precede the request for the personal data with notice to X,
describing the personal data and the purpose of its processing.
(2) Where a Data Principal has given her consent for the processing of her personal
data before the date of commencement of this Act,—
(a) the Data Fiduciary shall, as soon as it is reasonably practicable, give to the
Data Principal a notice informing her,––
(i) the personal data and the purpose for which the same has been
processed;
  (ii) the manner in which she may exercise her rights under sub-section (4)
of section 6 and section 13; and
 (iii) the manner in which the Data Principal may make a complaint to the
Board,
in such manner and as may be prescribed.
Grounds for
processing
personal data.
Notice.

(b) the Data Fiduciary may continue to process the personal data until and
unless the Data Principal withdraws her consent.
Illustration.
X, an individual, gave her consent to the processing of her personal data for an online
shopping app or website operated by Y, an e-commerce service provider, before the
commencement of this Act. Upon commencement of the Act, Y shall, as soon as practicable,
give through email, in-app notification or other effective method information to X, describing
the personal data and the purpose of its processing.
(3) The Data Fiduciary shall give the Data Principal the option to access the contents
of the notice referred to in sub-sections (1) and (2) in English or any language specified in
the Eighth Schedule to the Constitution.', 'NOTIFIED_PHASED_18MO', '2027-05-13', 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf', '', '[-0.067444,0.032741,-0.035240,-0.079359,-0.021923,-0.016247,0.071213,0.038697,0.014685,-0.005630,0.063987,0.021650,0.001317,-0.059940,0.034756,-0.007601,0.051273,-0.054168,-0.080456,0.090119,0.064272,-0.024622,-0.010155,0.015536,-0.027262,-0.010617,0.052881,-0.024505,0.015415,-0.009240,0.054829,0.049284,0.043026,0.030413,0.019284,-0.059547,0.027373,0.021953,-0.059828,-0.033855,-0.047235,-0.093945,-0.033473,0.071239,0.024747,0.059163,0.044537,0.055218,-0.056853,0.063646,-0.083416,-0.025649,-0.015232,0.069990,-0.099442,-0.007302,0.049973,-0.035672,0.022543,0.068476,-0.050290,0.000855,0.004988,0.050639,0.053450,0.021376,-0.025042,-0.032982,0.049680,0.005219,-0.019213,-0.044308,-0.091259,0.009194,-0.044651,-0.049714,-0.074022,0.039800,-0.003112,-0.065212,-0.015502,0.053559,0.033193,0.021575,-0.046418,-0.043043,-0.016245,0.031657,-0.034061,-0.007017,0.035873,0.081769,-0.008759,0.003048,0.005208,-0.006524,-0.048024,-0.076232,0.091108,0.003473,0.035812,0.084559,0.016124,0.075950,0.005460,-0.050060,0.016207,0.020568,0.009725,0.036210,-0.056452,-0.018457,-0.030392,-0.051008,0.028775,0.022817,-0.110618,0.103418,0.008649,-0.018404,0.023956,0.036339,-0.025816,-0.032079,0.028271,-0.068057,-0.036281,0.000000,-0.012100,0.042021,-0.043170,-0.008438,-0.022881,-0.021637,-0.026617,-0.027521,-0.036559,0.093488,0.037163,0.002898,0.018157,-0.020674,-0.022257,0.055742,0.024211,0.042371,0.092715,0.107234,0.130713,-0.049856,0.070645,0.026654,0.026393,0.007380,-0.037363,0.033885,0.033166,-0.008857,0.020501,-0.091511,0.046832,-0.005941,0.102544,0.008164,0.032308,-0.066160,0.014473,0.007098,0.043399,0.031802,0.047546,0.019842,-0.081550,0.036196,-0.002723,0.018799,-0.007122,0.063300,-0.016120,0.002184,-0.069800,-0.068179,-0.026986,0.036840,-0.024610,-0.058873,-0.025090,-0.088938,-0.003452,-0.036474,-0.048202,0.016559,-0.104