INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-act-2023-section-6-subsections-6-to-10', 'dpdp-act-2023', 'The Digital Personal Data Protection Act, 2023', 'Section 6', 'Section 6 — Consent Cessation, Managers & Burden of Proof',
    'Section 6 (Continued):
(6) If a Data Principal withdraws her consent to the processing of personal data under
sub-section (5), the Data Fiduciary shall, within a reasonable time, cease and cause its Data
Processors to cease processing the personal data of such Data Principal unless such
processing without her consent is required or authorised under the provisions of this Act
or the rules made thereunder or any other law for the time being in force in India.
Consent.

Illustration.
X, a telecom service provider, enters into a contract with Y, a Data Processor, for
emailing telephone bills to the customers of X. Z, a customer of X, who had earlier given her
consent to X for the processing of her personal data for emailing of bills, downloads the
mobile app of X and opts to receive bills only on the app. X shall itself cease, and shall
cause Y to cease, the processing of the personal data of Z for emailing bills.
(7) The Data Principal may give, manage, review or withdraw her consent to the Data
Fiduciary through a Consent Manager.
(8) The Consent Manager shall be accountable to the Data Principal and shall act on
her behalf in such manner and subject to such obligations as may be prescribed.
(9) Every Consent Manager shall be registered with the Board in such manner and
subject to such technical, operational, financial and other conditions as may be prescribed.
(10) Where a consent given by the Data Principal is the basis of processing of
personal data and a question arises in this regard in a proceeding, the Data Fiduciary shall
be obliged to prove that a notice was given by her to the Data Principal and consent was
given by such Data Principal to the Data Fiduciary in accordance with the provisions of this
Act and the rules made thereunder.', 'NOTIFIED_PHASED_1YR', '2026-11-13', 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf', '', '[-0.077743,0.057409,-0.024290,-0.066360,-0.001387,-0.048803,0.074048,0.000399,0.010341,0.029777,0.077923,0.029408,0.054308,-0.027577,-0.011697,0.020829,0.043428,-0.072439,-0.126665,0.084340,0.055265,0.047297,0.001762,0.003949,-0.026790,0.033471,0.015009,-0.063799,0.001880,-0.023529,0.029917,0.045000,0.008070,0.056098,-0.005449,-0.077142,0.020122,0.013636,-0.012498,-0.023676,-0.009107,-0.033982,-0.054514,0.020201,0.022675,0.037075,0.015926,0.018771,-0.095907,0.027358,-0.069196,-0.000711,-0.061848,0.143706,-0.059948,-0.039700,0.063250,-0.019102,0.000676,0.065529,-0.089612,0.026182,-0.065235,-0.006894,0.047614,0.032266,-0.003056,-0.030420,0.011392,0.022890,-0.011855,-0.039248,-0.050550,0.032618,-0.015324,-0.038783,-0.060766,0.012693,0.006100,-0.075850,-0.001468,0.066959,0.086109,0.007452,-0.064078,-0.056963,-0.029500,0.033020,0.012986,-0.032372,0.049400,0.094139,0.050486,0.039298,-0.003104,-0.017704,-0.035744,-0.088063,0.024546,0.004570,0.006345,0.047117,-0.081291,0.020785,-0.043898,-0.061823,0.025082,0.006335,-0.040834,0.053341,-0.054572,-0.015439,-0.047958,-0.040654,0.024305,0.017377,-0.089346,0.127126,0.003187,-0.021455,-0.059702,0.032475,-0.011587,-0.021945,0.002801,-0.086377,-0.003280,0.000000,-0.068890,0.015062,-0.041009,-0.023457,-0.008550,0.030718,0.000889,0.028155,-0.005807,0.060409,-0.016001,-0.021648,0.035776,-0.042502,0.028349,-0.014476,0.063244,0.031447,0.058848,0.101134,0.137648,-0.001485,0.066681,0.017071,0.013302,-0.009255,-0.053324,0.020653,0.052011,0.000996,-0.017016,-0.017068,0.031327,0.045379,0.064154,0.056964,0.004405,-0.048250,0.000572,0.012273,0.022703,0.043361,-0.003168,0.029848,-0.087797,-0.012755,0.059886,-0.023810,-0.008307,0.038723,-0.003773,0.025468,-0.015325,-0.042087,0.002703,0.023660,-0.000558,-0.054580,0.001685,-0.049689,0.025709,-0.066102,-0.057343,0.032234,-0.070413,-0.0