to ensure effective observance of  the provisions of this Act and the rules made thereunder.', 'NOTIFIED_PHASED_18MO', '2027-05-13', 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf', '', '[-0.048092,0.007136,0.012490,-0.017910,-0.030350,-0.027889,0.067875,0.009640,-0.043204,0.005888,0.073233,-0.000830,0.033482,0.003413,-0.069850,0.010071,0.048370,-0.017160,-0.075799,0.014984,0.058969,0.029907,-0.032039,0.013389,-0.002743,0.044252,-0.005671,-0.044618,-0.022534,-0.044605,-0.005646,0.009384,0.087192,0.047781,-0.034106,0.012578,-0.028195,0.043509,-0.022936,0.001516,-0.019980,-0.074757,-0.004145,0.009223,-0.020569,0.027444,0.056478,-0.027985,-0.063329,0.093067,-0.137348,0.026666,0.008193,0.118564,0.008029,-0.033921,-0.002136,-0.046463,-0.025104,0.035521,0.003886,-0.041528,-0.032551,0.002505,0.157331,-0.017974,-0.023788,-0.050918,-0.042999,0.003178,0.011534,-0.001906,-0.089859,0.052250,0.014788,-0.048330,-0.135818,0.005700,0.034579,-0.060878,-0.008023,0.056847,0.032945,-0.005037,0.003091,-0.090943,0.013509,-0.051870,-0.036500,0.030752,0.021684,0.001892,-0.008549,0.016743,-0.052028,0.039075,-0.044454,-0.087935,0.091780,-0.002751,0.010031,0.047231,-0.082806,0.062944,-0.076471,-0.103947,-0.026488,0.044669,-0.020893,-0.004667,-0.042596,0.012507,-0.085553,-0.059699,0.018331,0.019854,-0.078820,0.086981,0.008323,-0.005790,-0.029012,-0.004948,0.051922,-0.017218,-0.012826,-0.060964,-0.089419,0.000000,-0.015404,-0.012141,-0.039950,-0.009589,-0.070272,-0.041093,-0.099861,-0.031148,0.005237,-0.014871,0.011515,0.118929,-0.017092,0.056009,0.043712,0.057121,-0.011037,0.065424,0.072807,-0.000072,0.162247,0.013238,0.035203,0.049235,0.085402,0.000896,-0.021661,0.093180,-0.018715,0.015089,0.017488,-0.014650,0.054371,-0.061660,0.096595,0.025274,-0.000811,-0.053507,-0.020358,0.028101,0.094934,0.035427,0.036927,0.005629,-0.042965,0.023412,0.029747,0.028838,0.005302,0.054600,0.062503,0.003712,0.042356,-0.017728,0.019609,0.015056,-0.040257,-0.072504,0.017453