INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-act-2023-section-8-subsections-7-to-8', 'dpdp-act-2023', 'The Digital Personal Data Protection Act, 2023', 'Section 8', 'Section 8 — Duty to Erase Personal Data & Deemed Purpose Cessation',
    'Section 8 (Continued):
(7) A Data Fiduciary shall, unless retention is necessary for compliance with any law
for the time being in force,—
(a) erase personal data, upon the Data Principal withdrawing her consent or as
General
obligations of
Data
Fiduciary.
53 of 2005.

soon as it is reasonable to assume that the specified purpose is no longer being
served, whichever is earlier; and
(b) cause its Data Processor to erase any personal data that was made available
by the Data Fiduciary for processing to such Data Processor.
Illustrations.
(I) X, an individual, registers herself on an online marketplace operated by Y, an
e-commerce service provider. X gives her consent to Y for the processing of her personal
data for selling her used car. The online marketplace helps conclude the sale. Y shall no
longer retain her personal data.
(II) X, an individual, decides to close her savings account with Y, a bank. Y is required
by law applicable to banks to maintain the record of the identity of its clients for a period of
ten years beyond closing of accounts. Since retention is necessary for compliance with law,
Y shall retain X’s personal data for the said period.
(8) The purpose referred to in clause (a) of sub-section (7) shall be deemed to no
longer be served, if the Data Principal does not––
(a) approach the Data Fiduciary for the performance of the specified purpose;
and
(b) exercise any of her rights in relation to such processing,
for such time period as may be prescribed, and different time periods may be prescribed for
different classes of Data Fiduciaries and for different purposes.', 'NOTIFIED_PHASED_18MO', '2027-05-13', 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf', '', '[-0.069501,0.024942,-0.026399,-0.036726,0.017220,0.027993,0.097644,0.009768,0.027556,-0.012861,0.122609,0.077372,0.002219,-0.041548,0.030196,0.010272,-0.013460,-0.023230,-0.072425,0.073471,0.036113,-0.031324,-0.056008,0.045283,-0.011396,0.021710,0.009177,-0.044600,-0.035484,-0.044212,0.023682,0.036727,0.022240,0.024461,0.051377,-0.047543,0.011944,0.029443,-0.032333,-0.051884,-0.052254,-0.093267,-0.067734,0.022690,0.018526,0.051371,0.004576,0.048913,-0.058442,0.075568,-0.027549,-0.002911,-0.053034,0.127296,-0.022559,-0.014814,0.081402,-0.009085,-0.074874,0.054425,-0.009334,0.009648,-0.020021,0.020183,0.052452,-0.004424,0.015717,-0.060226,-0.003726,0.022162,-0.011634,-0.076760,-0.099112,0.020731,-0.014983,-0.042909,-0.053087,0.017040,-0.018292,-0.031892,0.034821,0.033884,0.020904,-0.005961,-0.090976,-0.068280,-0.050010,-0.053955,0.000437,-0.033730,0.070287,0.066094,0.036736,0.002388,0.014885,-0.034090,-0.010599,0.007362,0.059348,0.026031,0.018287,0.049129,-0.020474,0.050194,-0.046094,-0.055998,0.026207,0.039969,-0.005432,0.042832,-0.039346,-0.012769,-0.056003,0.051768,0.025061,0.053399,-0.109351,0.118540,-0.014235,-0.020080,0.016489,0.102666,0.025487,0.011163,-0.025136,-0.023763,-0.006367,0.000000,-0.069453,-0.013907,-0.076642,-0.011348,-0.000243,-0.011380,0.007230,-0.001138,-0.056143,0.058970,0.018729,0.034902,-0.029178,0.015275,0.020904,0.009244,0.033390,0.048297,0.117439,0.027846,0.161649,0.033364,0.039820,0.063039,0.004497,-0.042699,-0.043447,0.026202,-0.011710,0.002544,0.004212,0.004528,0.067220,0.015554,0.070408,0.036440,0.033448,-0.088567,-0.000967,-0.010396,0.071529,0.095785,0.032847,0.031774,-0.081762,-0.065399,0.037630,0.065211,-0.046478,0.106334,0.030640,0.008872,-0.046073,-0.052503,-0.046423,-0.003273,-0.031918,-0.090212,-0.046310,-0.077726,0.060018,-0.029756,0