INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-act-2023-section-10', 'dpdp-act-2023', 'The Digital Personal Data Protection Act, 2023', 'Section 10', 'Section 10 — Significant Data Fiduciary',
    '10. (1) The Central Government may notify any Data Fiduciary or class of Data
Fiduciaries as Significant Data Fiduciary, on the basis of an assessment of such relevant
factors as it may determine, including—
Processing of
personal data
of children.
Additional
obligations of
Significant
Data
Fiduciary.

(a) the volume and sensitivity of personal data processed;
(b) risk to the rights of  Data Principal;
(c) potential impact on the sovereignty and integrity of India;
(d) risk to electoral democracy;
(e) security of the State; and
(f) public order.
(2) The Significant Data Fiduciary shall—
(a) appoint a Data Protection Officer who shall—
(i) represent the Significant Data Fiduciary under the provisions of this
Act;
(ii) be based in India;
(iii) be an individual responsible to the Board of Directors or similar
governing body of the Significant Data Fiduciary; and
(iv) be the point of contact for the grievance redressal mechanism under
the provisions of this Act;
(b) appoint an independent data auditor to carry out data audit, who shall
evaluate the compliance of the Significant Data Fiduciary in accordance with the
provisions of this Act; and
(c) undertake the following other measures, namely:—
(i) periodic Data Protection Impact Assessment, which shall be a process
comprising a description of the rights of Data Principals and the purpose of
processing of their personal data, assessment and management of the risk to
the rights of the Data Principals, and such other matters regarding such process
as may be prescribed;
(ii) periodic audit; and
(iii) such other measures, consistent with the provisions of this Act, as
may be prescribed.
CHAPTER III
RIGHTS AND DUTIES OF DATA PRINCIPAL', 'NOTIFIED_PHASED_18MO', '2027-05-13', 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf', '', '[-0.047718,0.021345,-0.017020,-0.017747,-0.007244,0.005070,0.069910,0.019713,-0.020724,0.026771,0.071755,-0.070172,0.042047,-0.022787,-0.058641,0.025306,0.039928,0.014611,-0.093919,0.050815,0.070616,0.038732,-0.011593,-0.011043,-0.005392,0.014887,0.018356,-0.071314,-0.058675,-0.055374,0.016235,-0.009118,0.033471,0.062623,-0.024057,-0.022178,0.031881,0.036416,0.006838,-0.035194,-0.003727,-0.016820,-0.005510,-0.013091,-0.036043,-0.035709,0.048023,-0.035916,-0.082628,0.085907,-0.096453,0.023668,-0.022890,0.117829,-0.015025,-0.115325,0.013964,-0.067628,-0.013727,0.051670,-0.058795,0.044515,-0.048032,0.003696,0.080116,-0.026974,0.008345,-0.024426,-0.007382,0.005525,0.008991,-0.015055,-0.021621,0.022118,-0.004761,-0.039058,-0.124818,0.087044,0.044529,-0.109485,0.030488,0.109999,0.086756,0.025026,-0.020221,-0.063344,0.020831,-0.026017,-0.072231,0.009806,0.075411,0.019062,0.031120,0.081123,0.037819,-0.039591,-0.060364,-0.067635,0.086189,-0.009729,-0.021733,0.025265,-0.098777,0.118217,-0.129330,-0.105460,-0.017163,-0.067632,-0.014812,0.009484,-0.038479,0.050770,-0.057343,-0.044217,-0.003388,-0.034457,-0.092876,0.089972,-0.001742,-0.041238,-0.008550,0.016191,0.034982,-0.031703,0.008459,-0.063069,-0.074888,0.000000,0.010709,0.035471,-0.018453,0.002312,-0.051550,-0.002771,-0.048101,-0.032263,-0.044690,0.048408,-0.047581,0.067443,0.027734,-0.060349,0.019465,0.098796,0.000557,0.053456,0.087143,0.038532,0.105460,-0.014947,0.075111,0.086615,0.097397,-0.018267,0.004037,0.066540,-0.037192,0.045395,0.002966,-0.040720,0.069177,-0.017990,0.056194,0.003539,-0.003610,-0.042812,-0.019203,0.036357,0.072197,0.009027,0.011800,0.023112,-0.028646,0.002058,0.038969,0.070598,0.017950,0.054139,0.015089,-0.007679,-0.019365,-0.055194,-0.009547,0.039351,-0.036307,-0.072300,0.001824,-0.037128,-0.019354,-0.051119,0.001044,-0.023288,-0.0