INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-act-2023-section-11', 'dpdp-act-2023', 'The Digital Personal Data Protection Act, 2023', 'Section 11', 'Section 11 — Right to access information about personal data',
    '11. (1) The Data Principal shall have the right to obtain from the Data Fiduciary to
whom she has previously given consent, including consent as referred to in clause (a) of
section 7 (hereinafter referred to as the said Data Fiduciary), for processing of personal
data, upon making to it a request in such manner as may be prescribed,—
(a) a summary of personal data which is being processed by such Data Fiduciary
and the processing activities undertaken by that Data Fiduciary with respect to such
personal data;
(b) the identities of all other Data Fiduciaries and Data Processors with whom
the personal data has been shared by such Data Fiduciary, along with a description of
the personal data so shared; and
(c) any other information related to the personal data of such Data Principal and
its processing, as may be prescribed.
(2) Nothing contained in clause (b) or clause (c) of sub-section (1) shall apply in
respect of the sharing of any personal data by the said Data Fiduciary with any other Data
Fiduciary authorised by law to obtain such personal data, where such sharing is pursuant
Right to
access
information
about personal
data.

to a request made in writing by such other Data Fiduciary for the purpose of prevention or
detection or investigation of offences or cyber incidents, or for prosecution or punishment
of offences.', 'NOTIFIED_PHASED_18MO', '2027-05-13', 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf', '', '[-0.067893,0.026638,-0.016683,-0.014282,-0.003677,0.032231,0.092807,0.005741,-0.028840,-0.001224,0.073817,-0.014185,0.024523,-0.038607,-0.026680,0.047625,0.027388,-0.036446,-0.114170,0.053441,0.069290,0.024234,-0.017846,0.047697,-0.004811,0.056457,0.038910,-0.030092,0.022488,-0.038854,0.007331,0.005401,0.034108,0.076936,0.021156,-0.050145,-0.007369,-0.014081,-0.019045,0.022292,-0.024651,-0.039869,-0.021577,0.031969,-0.029956,0.039651,0.002231,0.008644,-0.049132,0.066688,-0.119651,0.034062,-0.023918,0.153221,-0.030187,-0.006068,-0.014131,-0.088093,0.001252,0.043725,-0.065959,-0.015344,0.009839,-0.003328,0.073732,-0.060348,-0.002713,-0.043645,-0.013352,0.025770,-0.022760,0.002432,-0.066758,0.030877,0.005416,-0.034638,-0.106170,0.010030,-0.005339,-0.126984,0.002122,0.115580,0.029084,-0.053560,-0.063931,-0.101430,-0.034871,-0.029572,-0.014590,0.009526,0.012867,0.006544,-0.014556,-0.000626,0.010731,0.013090,-0.071178,-0.053762,0.085985,-0.013999,-0.037098,0.058261,-0.069947,0.037043,-0.087399,-0.049144,-0.028103,0.024221,0.001041,0.068140,-0.022106,-0.004169,-0.063507,-0.023885,0.047006,0.011634,-0.047356,0.088496,0.037366,-0.043935,-0.025742,-0.011292,0.035724,0.019886,0.000196,-0.128275,-0.106375,0.000000,0.014869,-0.031781,-0.019973,-0.006711,-0.023300,0.028900,-0.034102,-0.049338,-0.039649,0.024967,0.025199,0.051828,-0.008541,-0.043213,-0.009359,0.044586,0.065189,0.038194,0.088644,0.054753,0.162252,0.047185,0.015957,0.094074,0.016026,-0.029460,-0.025754,0.017986,-0.004080,0.010928,-0.028298,0.012937,0.028853,-0.013651,0.110357,0.051465,0.024980,-0.050201,0.016452,0.058928,0.064928,0.009318,0.054067,-0.051044,-0.089525,-0.033406,0.020661,0.101644,-0.007901,0.082663,0.005420,0.005876,-0.013969,-0.074248,0.034868,0.036376,-0.101533,0.000593,0.033250,-0.028054,-0.010078,-0.014761,0.001103,-0.020445,-0.099798,-0.064926,0.008917,