INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-act-2023-section-13', 'dpdp-act-2023', 'The Digital Personal Data Protection Act, 2023', 'Section 13', 'Section 13 — Right of grievance redressal',
    '13. (1) A Data Principal shall have the right to have readily available means of grievance
redressal provided by a Data Fiduciary or Consent Manager in respect of any act or omission
of such Data Fiduciary or Consent Manager regarding the performance of its obligations in
relation to the personal data of such Data Principal or the exercise of her rights under the
provisions of this Act and the rules made thereunder.
(2) The Data Fiduciary or Consent Manager shall respond to any grievances referred
to in sub-section (1) within such period as may be prescribed from the date of its receipt for
all or any class of Data Fiduciaries.
(3) The Data Principal shall exhaust the opportunity of redressing her grievance
under this section before approaching the Board.', 'NOTIFIED_PHASED_18MO', '2027-05-13', 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf', '', '[-0.037212,0.040485,0.023193,-0.005632,-0.016478,0.009910,0.054551,0.006580,-0.056560,0.002056,0.098103,-0.008141,0.003584,-0.045530,0.009447,0.064266,0.057596,-0.022201,-0.083441,0.032222,0.071864,0.009379,-0.051356,0.052951,-0.057229,0.057331,0.050227,-0.043614,0.002710,-0.031996,-0.035017,0.001533,0.042095,0.078623,0.033664,0.001788,0.027588,0.022098,-0.038686,0.034495,-0.001330,-0.012622,-0.016257,0.033518,-0.015086,0.035098,0.064149,-0.019929,-0.131507,0.020749,-0.026817,0.015520,0.004091,0.166272,-0.056794,-0.065636,0.006009,-0.053406,0.005713,0.058972,-0.070489,-0.030109,-0.074573,-0.021418,0.068094,-0.057231,0.006938,-0.022945,-0.025156,0.086534,-0.018395,-0.036154,-0.056501,0.006665,0.021457,-0.010623,-0.118767,0.037420,0.095018,-0.148675,0.036733,0.089821,0.043145,0.019877,-0.001685,-0.123358,0.000435,-0.000473,-0.020239,0.026846,0.054201,0.023634,0.088727,0.021806,-0.043863,0.033267,-0.092623,-0.095852,0.071163,0.012895,-0.038230,0.058717,-0.100814,0.057395,-0.089320,-0.124868,-0.037761,-0.004211,-0.057187,0.038097,-0.032884,0.006263,-0.016188,-0.098612,0.033098,0.004123,-0.100790,0.083905,-0.030760,-0.087821,-0.012221,-0.027101,-0.019587,0.024575,0.008573,-0.084113,-0.105197,0.000000,0.033690,-0.009317,-0.059134,-0.013719,0.039322,0.017345,-0.028986,-0.018488,0.041526,0.034608,-0.008532,0.026084,-0.009674,-0.062114,-0.026980,0.087842,0.041770,0.102367,0.046017,0.035246,0.114402,0.011628,0.038016,0.013907,0.056131,0.013455,-0.075673,0.022035,-0.006543,0.007714,-0.003888,-0.025782,0.048104,0.028018,0.087396,0.044250,0.029895,-0.043987,0.010825,0.041471,0.041352,0.031001,0.037967,-0.024125,-0.000663,-0.013162,0.038639,-0.001328,0.016105,0.084920,0.022113,0.017279,0.008475,-0.038863,0.046359,-0.019966,-0.072783,-0.020834,0.054535,-0.020736,0.029680,0.012432,0.005869,-0.019433,-0.