INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-act-2023-section-21', 'dpdp-act-2023', 'The Digital Personal Data Protection Act, 2023', 'Section 21', 'Section 21 — Disqualification for appointment and continuation as Member',
    '21. (1) A person shall be disqualified for being appointed and continued as the
Chairperson or a Member, if she—
(a) has been adjudged as an insolvent;
(b) has been convicted of an offence, which in the opinion of the Central
Government, involves moral turpitude;
(c) has become physically or mentally incapable of acting as a Member;
(d) has acquired such financial or other interest, as is likely to affect prejudicially
her functions as a Member; or
(e) has so abused her position as to render her continuance in office prejudicial
to the public interest.
(2) The Chairperson or Member shall not be removed from her office by the Central
Government unless she has been given an opportunity of being heard in the matter.', 'IN_FORCE', '2025-11-13', 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf', '', '[-0.006248,0.002916,-0.009963,-0.005861,-0.057438,0.060915,0.057303,-0.051850,-0.006206,0.016022,0.085778,0.061401,0.053932,-0.083588,-0.024743,-0.009033,0.010405,0.020129,-0.014346,0.103312,0.048938,-0.071963,-0.132710,0.013061,-0.019665,-0.081056,-0.050180,-0.045554,0.033128,-0.046766,-0.036309,-0.005788,0.008890,0.028998,0.036686,0.011590,0.027965,-0.036887,0.033422,-0.064048,0.079474,-0.021812,-0.046817,-0.070573,-0.034370,-0.036699,-0.028855,0.007377,-0.144186,-0.091788,-0.051066,-0.035215,0.023809,0.065478,-0.019022,-0.063562,-0.035718,-0.024292,0.039050,0.038260,0.012628,0.044388,-0.065531,0.017339,0.025518,-0.040278,0.020491,-0.085835,0.053702,0.058281,0.029340,-0.023017,-0.019894,-0.040272,-0.069570,0.011738,0.029715,0.041537,0.115435,-0.030402,0.014500,0.052015,0.054512,-0.050087,0.002944,-0.062913,-0.039522,-0.071555,0.009456,0.021029,0.057982,0.056828,0.098921,-0.025186,0.030003,0.027516,-0.025946,0.013212,-0.030620,0.063050,-0.053977,0.058766,-0.049987,-0.000722,-0.048354,-0.030019,0.041726,-0.069400,0.001318,-0.009524,-0.055110,0.007427,0.028860,-0.084527,-0.014980,0.117938,-0.033790,0.004886,-0.033546,-0.118352,0.022539,0.031465,0.024291,0.011471,0.012341,-0.061451,-0.037077,0.000000,-0.043072,-0.059201,-0.052143,-0.005810,0.014374,0.013970,-0.043152,-0.070401,0.053505,0.060698,0.042648,-0.071222,0.040201,-0.054876,0.038472,0.015609,0.068412,-0.021163,-0.003740,0.029662,0.099492,0.085191,-0.004152,0.033366,-0.040427,-0.029102,-0.036905,-0.063877,-0.046190,0.048754,0.059624,0.030187,-0.021184,0.049165,0.059737,-0.015753,-0.016126,0.016108,0.048663,-0.014541,-0.047716,0.026997,0.084953,0.001858,0.023031,-0.036413,0.040744,0.006389,-0.002554,0.081350,0.034964,0.014980,0.047371,0.036239,-0.020121,-0.000227,0.022757,0.032222,0.027406,-0.037934,0.068643,-0.0