INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-act-2023-section-22', 'dpdp-act-2023', 'The Digital Personal Data Protection Act, 2023', 'Section 22', 'Section 22 — Resignation by Members and filling of vacancy',
    '22. (1) The Chairperson or any other Member may give notice in writing to the Central
Government of resigning from her office, and such resignation shall be effective from the
date on which the Central Government permits her to relinquish office, or upon expiry of a
period of three months from the date of receipt of such notice, or upon a duly appointed
successor entering upon her office, or upon the expiry of the term of her office, whichever
is earliest.
(2) A vacancy caused by the resignation or removal or death of the Chairperson or
any other Member, or otherwise, shall be filled by fresh appointment in accordance with the
provisions of this Act.
(3) The Chairperson and any other Member shall not, for a period of one year from the
date on which they cease to hold such office, except with the previous approval of the
Central Government, accept any employment, and shall also disclose to the Central
Government any subsequent acceptance of employment with any Data Fiduciary against
whom proceedings were initiated by or before such Chairperson or other Member.', 'IN_FORCE', '2025-11-13', 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf', '', '[-0.002098,0.001700,0.056293,0.013042,-0.040310,0.073550,-0.039002,-0.027673,0.041420,0.027817,0.025754,0.024309,0.020777,-0.104502,-0.054191,0.001286,-0.013819,0.067715,-0.003598,0.026461,0.040947,-0.045413,-0.079644,0.029115,-0.023711,-0.064067,-0.039427,-0.019430,0.064931,0.000022,0.002414,-0.005965,-0.004526,0.000905,0.043285,0.016350,0.015529,-0.042170,0.044213,-0.070030,0.021183,-0.013694,-0.008770,-0.047540,-0.008984,0.011459,0.004399,-0.000321,-0.125585,-0.000788,0.026858,-0.091087,-0.048698,0.066030,0.003621,-0.027627,0.045171,-0.052930,0.027696,0.028636,0.030413,-0.004750,-0.077761,0.013065,-0.056704,-0.045330,0.056868,-0.120288,0.072907,-0.013072,-0.048915,-0.058555,-0.051212,0.007168,-0.109468,0.022167,0.044737,0.075097,0.047562,-0.038021,0.036182,0.085806,0.065154,0.012745,-0.012782,-0.082028,-0.034110,-0.006260,0.018133,-0.013455,0.069017,0.088123,0.037849,-0.026256,-0.057185,-0.028182,-0.013950,0.038103,0.050911,0.054307,-0.008644,0.007211,-0.091128,-0.019599,-0.042786,0.006420,-0.011233,-0.095890,0.002446,-0.031777,-0.092644,-0.017612,-0.026014,-0.070524,-0.009334,0.138377,-0.090603,0.064076,-0.032001,-0.040398,0.011195,0.042872,-0.017244,-0.073431,0.023025,-0.013685,0.032568,0.000000,-0.029902,-0.018433,-0.044533,0.121980,0.053849,0.005942,-0.002971,-0.031520,0.080628,0.029122,0.056392,-0.070243,0.040880,-0.153103,-0.011546,0.017302,0.150476,-0.065562,0.014234,0.029050,0.133876,0.013355,-0.008336,0.054325,0.020224,0.026109,-0.040972,-0.042965,-0.072915,0.025841,0.020726,0.041543,-0.019870,0.020223,0.000338,-0.046416,0.013399,0.004474,0.054494,-0.076919,0.018758,0.050192,0.041110,-0.001989,0.021306,-0.103469,0.124984,0.068079,0.117618,0.033234,0.066094,0.008211,0.007914,0.072073,-0.002038,0.050603,-0.011425,-0.019131,0.034930,-0.033790,0.067349,0.016415,