INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-act-2023-section-23', 'dpdp-act-2023', 'The Digital Personal Data Protection Act, 2023', 'Section 23', 'Section 23 — Proceedings of Board',
    '23. (1) The Board shall observe such procedure in regard to the holding of and
transaction of business at its meetings, including by digital means, and authenticate its
orders, directions and instruments in such manner as may be prescribed.
(2) No act or proceeding of the Board shall be invalid merely by reason of—
(a) any vacancy in or any defect in the constitution of the Board;
(b) any defect in the appointment of a person acting as the Chairperson or other
Member of the Board; or
(c) any irregularity in the procedure of the Board, which does not affect the
merits of the case.
(3) When the Chairperson is unable to discharge her functions owing to absence,
illness or any other cause, the senior-most Member shall discharge the functions of the
Chairperson until the date on which the Chairperson resumes her duties.', 'IN_FORCE', '2025-11-13', 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf', '', '[-0.021712,0.029816,-0.015287,-0.027531,-0.078030,0.049728,0.026117,-0.036078,0.039694,-0.003940,0.044714,0.074757,-0.011839,-0.030579,-0.054091,-0.056125,0.042133,0.025386,-0.029062,0.105991,0.016198,-0.018559,-0.123728,0.026243,-0.092470,-0.070811,0.005829,-0.094809,0.047934,-0.063559,0.012216,0.021464,0.008665,0.010463,0.047757,0.027459,0.021952,-0.040373,0.019193,-0.042165,0.014463,-0.049986,-0.036789,0.004300,0.005878,0.017001,-0.001142,-0.045097,-0.083836,0.019451,-0.053364,-0.073425,-0.020843,0.056362,-0.067833,-0.022154,0.038517,-0.095124,0.026098,-0.009268,-0.027790,0.019264,-0.020464,0.050696,0.047562,-0.003510,0.048521,-0.113361,0.015013,0.066916,-0.020962,-0.057297,-0.076891,0.045549,-0.073038,0.003000,-0.003010,0.015904,0.068498,-0.058431,0.018090,0.046772,0.069259,-0.015391,0.001149,-0.035347,-0.047055,0.017343,0.002145,-0.012084,0.029573,0.087253,0.040516,-0.010915,-0.074367,-0.035574,0.016167,0.015732,0.070974,0.045015,-0.031982,0.078237,-0.032972,0.004676,-0.102574,-0.027967,0.014679,-0.080744,-0.005562,-0.024637,-0.045577,0.028652,0.010906,-0.090428,-0.036047,0.078208,-0.046249,0.034542,0.004183,-0.093742,0.008723,0.045368,0.070447,-0.004873,-0.032374,-0.034182,0.058817,-0.000000,-0.027033,-0.072808,-0.056922,-0.007309,0.080185,-0.007928,0.024463,-0.110055,0.076605,0.057524,0.035070,-0.061658,0.061168,-0.117918,-0.023961,0.004069,0.125977,0.007580,0.007635,0.077957,0.133040,-0.077383,0.036980,0.104812,0.036200,0.015365,-0.010484,-0.006759,-0.017201,0.035199,0.009481,-0.019194,-0.036787,0.052064,0.047519,0.025854,-0.018519,0.009305,0.044011,-0.036816,-0.064589,0.003470,0.030421,0.017781,0.004760,-0.042671,0.071363,0.048911,0.036463,0.016991,-0.009043,-0.014386,0.111614,-0.027077,0.054259,-0.002960,0.028315,-0.002625,-0.010143,-0.044890,0.098991,-0.002868,-0.08