INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-act-2023-section-24', 'dpdp-act-2023', 'The Digital Personal Data Protection Act, 2023', 'Section 24', 'Section 24 — Officers and employees of Board',
    '24. The Board may, with previous approval of the Central Government, appoint such
officers and employees as it may deem necessary for the efficient discharge of its functions
under the provisions of this Act, on such terms and conditions of appointment and service
