POWERS, FUNCTIONS AND PROCEDURE TO BE FOLLOWED BY BOARD', 'IN_FORCE', '2025-11-13', 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf', '', '[0.038108,0.011776,-0.057435,-0.016566,-0.067165,0.066547,0.046475,-0.012306,-0.004148,0.022554,-0.049372,0.007010,-0.007832,-0.025771,-0.072060,0.013635,0.001883,0.019236,-0.042073,0.050051,0.037990,-0.010521,-0.068141,-0.012319,-0.076859,-0.052311,-0.047217,-0.040996,0.043070,-0.048314,-0.013085,0.013469,0.045518,0.024984,-0.016548,0.060523,0.014599,-0.009909,0.023918,-0.051758,-0.003933,0.001465,0.008390,0.001671,0.003369,0.064154,0.015930,-0.007248,-0.074024,-0.021993,-0.032546,-0.127421,-0.019419,-0.024004,-0.067436,0.004007,0.003371,-0.098356,0.071679,-0.048096,-0.014043,0.041447,-0.018145,0.039340,0.081346,-0.056761,0.005516,-0.053146,-0.066513,0.040082,0.032900,-0.064175,-0.020077,0.004301,-0.034588,0.030682,-0.048461,0.054017,0.112661,-0.073918,-0.003022,-0.004694,0.024549,0.003018,0.014283,-0.007338,0.010991,0.006001,-0.001385,0.048398,0.057340,0.049621,0.090533,-0.011533,-0.085762,-0.001336,-0.036915,-0.053398,0.010902,0.049485,-0.032104,0.084606,-0.010034,-0.013069,-0.134346,0.001587,0.003270,-0.015535,0.009919,0.001444,-0.091881,0.020643,-0.036127,-0.082002,-0.017165,0.059238,-0.006131,0.061665,0.024218,-0.086163,0.044060,0.048343,0.055738,0.019033,-0.016243,0.010830,0.009068,0.000000,-0.043806,-0.001967,-0.008218,0.065043,0.050848,0.013540,0.034405,-0.083727,-0.022329,0.076679,-0.019223,0.004755,0.128976,-0.060344,-0.011472,0.010505,0.040491,-0.052726,-0.032611,0.002946,0.126012,0.013190,0.063695,0.070886,0.123840,-0.032084,-0.006347,0.002042,0.031746,0.018539,0.028312,-0.053842,-0.109843,0.008754,0.013790,0.009332,0.058170,-0.041630,0.084432,0.007761,-0.052015,-0.011308,0.016017,-0.018754,-0.003484,0.009012,0.079884,0.083810,0.067858,0.011340,-0.042690,-0.038076,0.058609,-0.040953,0.084577,-0.012409,0.008622,0.075825,0.014164,-0.043803,0.058788,-0.020802,-0.067984,0.059292,-0.0