INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-act-2023-section-29', 'dpdp-act-2023', 'The Digital Personal Data Protection Act, 2023', 'Section 29', 'Section 29 — Appeal to Appellate Tribunal',
    '29. (1) Any person aggrieved by an order or direction made by the Board under this
Act may prefer an appeal before the Appellate Tribunal.
(2) Every appeal under sub-section (1) shall be filed within a period of sixty days from
the date of receipt of the order or direction appealed against and it shall be in such form and
manner and shall be accompanied by such fee as may be prescribed.
(3) The Appellate Tribunal may entertain an appeal after the expiry of the period
specified in sub-section (2), if it is satisfied that there was sufficient cause for not preferring
the appeal within that period.
(4) On receipt of an appeal under sub-section (1), the Appellate Tribunal may, after
giving the parties to the appeal, an opportunity of being heard, pass such orders thereon as
it thinks fit, confirming, modifying or setting aside the order appealed against.
Appeal to
Appellate
Tribunal.
5 of 1908.

(5) The Appellate Tribunal shall send a copy of every order made by it to the Board
and to the parties to the appeal.
(6) The appeal filed before the Appellate Tribunal under sub-section (1) shall be dealt
with by it as expeditiously as possible and endeavour shall be made by it to dispose of the
appeal finally within six months from the date on which the appeal is presented to it.
(7) Where any appeal under sub-section (6) could not be disposed of within the
period of six months, the Appellate Tribunal shall record its reasons in writing for not
disposing of the appeal within that period.
(8) Without prejudice to the provisions of section 14A and section 16 of the Telecom
Regulatory Authority of India Act, 1997, the Appellate Tribunal shall deal with an appeal
under this section in accordance with such procedure as may be prescribed.
(9) Where an appeal is filed against the orders of the Appellate Tribunal under this
Act, the provisions of section 18 of the Telecom Regulatory Authority of India Act, 1997
shall apply.
(10) In respect of appeals filed under the provisions of this Act, the Appellate Tribunal
shall, as far as practicable, function as a digital office, with the receipt of appeal, hearing and
pronouncement of decisions in respect of the same being digital by design.', 'NOTIFIED_PHASED_18MO', '2027-05-13', 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf', '', '[-0.058146,0.028945,0.054857,-0.083365,0.019795,0.002913,0.009674,0.054534,0.017583,0.041895,0.042549,0.029099,-0.020642,-0.002411,-0.025181,0.025399,0.029640,0.013326,-0.012441,0.037284,0.088230,0.049096,-0.052681,-0.060302,-0.015804,-0.068735,-0.099901,0.000046,0.061740,-0.043226,0.003234,0.060690,0.006896,0.016950,0.004252,-0.013096,0.022722,-0.063736,-0.012387,-0.003875,-0.009996,0.022459,0.006079,-0.033334,0.035600,0.009429,0.016083,-0.061285,-0.069257,0.002731,-0.059573,-0.052944,-0.015396,0.069873,-0.057156,-0.000669,0.047886,0.020571,-0.017508,-0.054550,-0.042034,-0.061396,-0.058338,-0.032834,-0.031622,-0.025205,0.042783,-0.012672,0.029130,0.048036,0.075728,0.011112,-0.004534,0.005613,-0.110289,0.047145,0.005777,0.043897,-0.006568,-0.092806,-0.046436,-0.018274,0.012596,-0.088317,0.032822,-0.092361,0.029869,0.031376,0.001009,0.045783,0.135868,-0.049993,0.017410,0.018743,0.037938,-0.021171,0.041607,0.003908,0.096832,0.072408,0.041637,0.053489,-0.066793,0.015147,0.012372,-0.056922,-0.071522,0.013498,0.002042,-0.050306,-0.111687,0.002331,0.082823,-0.050282,-0.067979,0.046448,0.061319,0.078901,0.058915,-0.050083,0.026129,0.074601,-0.014266,0.020022,0.077935,0.062569,0.042958,0.000000,-0.030686,-0.050142,-0.063681,-0.031814,-0.052084,-0.081034,0.049946,0.004597,-0.004506,-0.025337,-0.054688,0.028591,0.075802,-0.043216,-0.071135,-0.007731,0.005145,-0.011123,-0.004286,0.005725,0.074469,-0.109009,-0.000945,0.039187,-0.071341,-0.086937,-0.004255,0.013362,-0.072736,0.008726,0.061132,0.026633,0.017528,0.024102,0.024225,0.040059,0.072986,0.000973,0.063884,-0.022304,-0.006775,0.036951,0.021459,-0.000288,0.007536,-0.078088,-0.044053,0.065168,0.070451,0.034893,0.056295,0.003747,0.117203,0.010345,0.006044,-0.007558,-0.062486,-0.018868,-0.017265,0.026368,0.068155,-0.01805