INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-act-2023-section-32', 'dpdp-act-2023', 'The Digital Personal Data Protection Act, 2023', 'Section 32', 'Section 32 — Voluntary undertaking',
    '32. (1) The Board may accept a voluntary undertaking in respect of any matter related
to observance of the provisions of this Act from any person at any stage of a proceeding
under section 28.
(2) The voluntary undertaking referred to in sub-section (1) may include an
undertaking to take such action within such time as may be determined by the Board, or
refrain from taking such action, and or publicising such undertaking.
(3) The Board may, after accepting the voluntary undertaking and with the consent of
the person who gave the voluntary undertaking vary the terms included in the voluntary
undertaking.
(4) The acceptance of the voluntary undertaking by the Board shall constitute a bar
on proceedings under the provisions of this Act as regards the contents of the voluntary
undertaking, except in cases covered by sub-section (5).
(5) Where a person fails to adhere to any term of the voluntary undertaking accepted
by the Board, such breach shall be deemed to be breach of the provisions of this Act and
the Board may, after giving such person an opportunity of being heard, proceed in accordance
with the provisions of section 33.
CHAPTER VIII
PENALTIES AND ADJUDICATION', 'NOTIFIED_PHASED_18MO', '2027-05-13', 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf', '', '[-0.001575,0.006134,0.028942,-0.062191,-0.027850,0.040046,0.045211,-0.023548,-0.043688,0.014716,0.078536,-0.047865,0.002880,0.000321,0.084441,-0.001180,0.032322,-0.003758,-0.005480,0.093226,0.049965,0.002413,-0.061670,0.016601,-0.037378,-0.051544,-0.035496,-0.013139,0.037177,-0.059161,0.023632,-0.011039,0.076191,0.043464,-0.002654,-0.013956,-0.003412,-0.105615,-0.023972,-0.024928,-0.032191,-0.024679,-0.055845,0.049319,0.028563,0.050399,-0.032080,-0.047478,-0.040291,-0.019971,-0.007919,-0.104074,-0.036993,0.022969,-0.133117,-0.037151,-0.020308,-0.046162,0.035980,-0.019947,-0.002231,-0.009430,-0.032737,0.003274,0.003014,0.008849,0.019910,-0.025132,0.044502,0.048324,0.029460,-0.069179,-0.028910,0.020702,-0.054545,-0.053698,-0.016805,0.053432,0.049022,-0.153806,-0.086958,0.000371,-0.038552,-0.072049,-0.025111,-0.059427,-0.003402,0.062914,0.105859,0.032042,0.018843,-0.021539,0.049856,-0.037161,0.030413,-0.048730,0.022711,0.003515,0.033991,0.033664,0.051476,0.102629,-0.055156,-0.007266,-0.054292,0.001360,-0.024780,-0.059893,-0.007125,0.002963,-0.083986,0.031396,0.071753,-0.069876,0.051570,0.053794,0.039986,0.056485,0.035061,-0.060752,0.007253,0.081171,0.064545,0.006951,-0.054489,-0.006986,0.004897,0.000000,0.000352,-0.047357,-0.092521,0.013461,0.039909,0.018623,-0.014002,0.016225,0.016862,0.095655,0.041150,-0.055751,0.073255,-0.006139,0.029190,-0.001526,0.053408,-0.001337,-0.007119,0.067809,0.087559,-0.067193,0.018352,0.124711,-0.019262,-0.084079,0.017342,-0.021869,-0.029548,0.006783,-0.004716,-0.021186,0.004596,-0.013733,0.034670,0.049836,0.042673,0.043867,-0.008513,-0.075824,-0.067448,0.001216,-0.011949,0.005208,-0.060205,-0.039257,0.049054,0.017804,-0.007924,0.066070,0.017920,0.018017,0.033871,-0.046300,0.004062,0.006392,-0.068175,0.057113,-0.022478,-0.059260,0.130910,0.022433,-0.026208,0.061369,-0.063331,0.0354