INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-act-2023-section-37', 'dpdp-act-2023', 'The Digital Personal Data Protection Act, 2023', 'Section 37', 'Section 37 — Power to block access to information in public interest',
    '37. (1) The Central Government or any of its officers specially authorised by it in this
behalf may, upon receipt of a reference in writing from the Board that—
(a) intimates the imposition of monetary penalty by the Board on a Data Fiduciary
in two or more instances; and
(b) advises, in the interests of the general public, the blocking for access by the
public to any information generated, transmitted, received, stored or hosted, in any
computer resource that enables such Data Fiduciary to carry on any activity relating
to offering of goods or services to Data Principals within the territory of India,
after giving an opportunity of being heard to that Data Fiduciary, on being satisfied that it
is necessary or expedient so to do, in the interests of the general public, for reasons to be
recorded in writing, by order, direct any agency of the Central Government or any intermediary
to block for access by the public or cause to be blocked for access by the public any such
information.
(2) Every intermediary who receives a direction issued under sub-section (1) shall be
bound to comply with the same.
(3) For the purposes of this section, the expressions “computer resource”,
“information” and “intermediary” shall have the meanings respectively assigned to them in
the Information Technology Act, 2000.
Crediting sums
realised by
way of
penalties to
Consolidated
Fund of India.
Protection of
action taken
in good faith.
Power to call
for
information.
Power of
Central
Government
to issue
directions.
21 of 2000.', 'NOTIFIED_PHASED_18MO', '2027-05-13', 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf', '', '[-0.076406,0.012444,-0.060068,-0.057081,0.008116,0.004807,0.130596,-0.015598,0.008147,0.000257,0.021646,-0.006402,0.062025,-0.038768,0.010961,-0.018956,0.048604,-0.059893,-0.036577,0.061598,0.095189,0.018419,-0.041341,0.002151,-0.061455,-0.010483,-0.028212,-0.105003,0.006661,-0.040152,-0.039186,-0.015289,0.024461,0.083693,0.010360,-0.024499,0.014020,0.018403,0.026372,-0.082477,0.023254,-0.011914,-0.000527,0.001134,-0.031625,0.034611,0.057741,0.014516,-0.123092,0.000103,-0.097446,0.008060,-0.002395,0.109939,-0.002452,-0.143133,0.054869,-0.049170,-0.012188,0.042648,-0.047037,-0.025691,-0.021213,0.005817,0.099966,-0.030077,-0.040667,0.030451,-0.021153,0.006948,0.003659,-0.012315,-0.028002,0.047231,0.006372,-0.049695,-0.097621,0.095216,0.041733,-0.146069,0.052076,0.030571,0.104414,0.019047,-0.093709,-0.042335,-0.000189,-0.005220,0.069091,-0.019938,0.070586,0.044970,0.059062,0.074741,-0.002411,-0.054794,0.005325,-0.065779,0.021084,0.024847,0.032571,0.076417,-0.019125,0.029271,-0.089090,-0.080052,-0.009258,0.012831,-0.023971,-0.003721,-0.106284,0.035221,-0.068016,-0.055771,-0.000221,-0.046950,-0.034353,0.071044,0.046928,-0.038870,-0.022812,0.048987,0.028724,-0.049782,0.003708,-0.103030,-0.037136,0.000000,-0.000473,0.019197,-0.043613,-0.051205,-0.005388,-0.025719,-0.045460,-0.042402,-0.012221,0.033259,-0.008899,0.057605,0.062154,-0.007297,0.067815,0.060060,0.045461,0.053032,0.137818,0.047872,0.103803,-0.006943,0.080757,0.069320,0.042813,-0.054753,-0.052277,-0.018740,0.072953,0.031276,0.052192,-0.018034,0.039925,-0.008056,0.092008,0.003346,0.033006,-0.073991,0.030651,0.019480,-0.022197,0.030034,0.014167,-0.020554,-0.044646,-0.001691,0.018838,0.064877,-0.066217,0.088409,-0.007248,0.052319,-0.014225,-0.036985,0.029244,0.021682,-0.013289,-0.042170,0.042213,-0.018491,0.039595,-0.017422,0.011801,-0.000923,-0.110991,-0.020859,0.018497,-0