INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-act-2023-section-39', 'dpdp-act-2023', 'The Digital Personal Data Protection Act, 2023', 'Section 39', 'Section 39 — Bar of jurisdiction of civil courts',
    '39. No civil court shall have the jurisdiction to entertain any suit or proceeding in
respect of any matter for which the Board is empowered under the provisions of this Act
and no injunction shall be granted by any court or other authority in respect of any action
