INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-act-2023-section-41', 'dpdp-act-2023', 'The Digital Personal Data Protection Act, 2023', 'Section 41', 'Section 41 — Laying of rules and notifications before Parliament',
    '41. Every rule made and every notification issued under section 16 and section 42 of
this Act shall be laid, as soon as may be after it is made, before each House of Parliament,
while it is in session, for a total period of thirty days which may be comprised in one session
or in two or more successive sessions, and if before the expiry of the session immediately
following the session or the successive sessions aforesaid, both Houses agree in making
any modification in the rule or notification or both Houses agree that the rule or notification
should not be made or issued, the rule or notification shall thereafter have effect only in
such modified form or be of no effect, as the case may be; so, however, that any such
modification or annulment shall be without prejudice to the validity of anything previously
done under that rule or notification.', 'IN_FORCE', '2025-11-13', 'https://www.meity.gov.in/static/uploads/2024/06/2bf1f0e9f04e6fb4f8fef35e82c42aa5.pdf', '', '[-0.004271,0.057036,0.073323,-0.085770,0.008375,0.020723,0.034363,-0.057477,-0.007926,0.039537,0.032724,0.035967,0.029539,0.052952,0.029562,0.043951,0.009816,-0.015855,-0.108396,0.034833,0.132805,0.006397,-0.064998,0.068497,-0.019799,-0.006897,0.007593,-0.018209,0.033856,-0.056954,0.003412,-0.005701,0.026991,-0.034489,0.040634,-0.081596,0.063454,-0.041467,0.073669,-0.063110,0.006662,-0.105032,-0.069224,0.022853,0.018906,0.060832,0.033109,-0.048212,-0.110738,0.026181,0.021389,-0.028710,0.002753,0.043488,0.032831,-0.068112,-0.052082,0.050398,0.005397,0.002037,-0.009373,-0.036244,-0.058792,0.004282,0.031743,-0.059005,0.019669,-0.091175,0.030479,0.078430,0.014098,-0.004173,0.045508,-0.019882,-0.066073,-0.010574,-0.037418,0.054388,0.000629,-0.134085,-0.099022,-0.014972,0.046031,-0.073972,0.018771,-0.103270,-0.022499,0.032567,0.025451,0.045150,0.023534,-0.048051,0.010588,0.037492,-0.092617,-0.065255,-0.038245,-0.002343,0.055976,0.106524,-0.039089,0.027741,-0.109589,0.056179,0.042401,-0.002403,-0.101803,-0.010404,0.007490,-0.045923,-0.066195,-0.011956,0.084222,-0.079301,-0.031898,0.032913,0.060942,0.081064,0.033860,-0.028775,0.071203,-0.030326,0.065457,0.001868,0.001360,0.047568,0.009349,0.000000,-0.022818,-0.026316,-0.102236,0.053019,0.069518,-0.039516,-0.030093,-0.007398,0.026000,-0.061968,0.070875,-0.039597,0.054872,-0.080611,-0.007540,0.023394,0.035411,0.027980,-0.001343,0.027711,0.067529,-0.021004,0.008459,0.066115,0.008018,-0.026223,0.027889,0.012136,-0.002044,0.034703,0.080788,0.030529,0.027931,0.009787,-0.036972,-0.006969,-0.033727,-0.073358,0.037310,-0.066261,0.018511,0.008809,-0.013510,-0.028567,-0.014220,-0.011096,0.010248,0.072034,0.059710,0.007090,0.090176,0.027932,0.067204,-0.006487,-0.026188,-0.016385,-0.105151,-0.008802,-0.002070,0.008497,0.075861,-0.017972,0.013175,-0.037946,-0.035888,-0.022199,0.007