INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-rules-2025-rule-2', 'dpdp-rules-2025', 'The Digital Personal Data Protection Rules, 2025', 'Rule 2', 'Rule 2 — Definitions (techno-legal measures, user account, verifiable consent)',
    '2. Definitions. — (1) In these rules, unless the context otherwise requires, – 
(a) “Act” means the Digital Personal Data Protection Act, 2023 (22 of 2023); 
(b) “techno-legal measures” means as referred to under rules 20 and 22; 
(c) “user account” means the online account registered by the Data Principal with the Data Fiduciary, and 
includes any profiles, pages, handles, email address, mobile number and other similar presences by means 
of which such Data Principal is able to access the services of such Data Fiduciary; and 
(d) “verifiable consent” means a consent as specified in rule 10 or 11. 
(2) The words and expressions used in these rules and not defined, but defined in the Act, shall have the 
same meanings respectively assigned to them in the Act.', 'IN_FORCE', '2025-11-13', 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf', '', '[-0.057710,-0.003652,-0.040503,-0.079636,0.014434,0.019163,0.089570,0.019188,-0.006626,0.015875,0.061159,-0.009529,0.068691,0.025644,-0.005498,-0.030436,0.010179,-0.058062,-0.052889,0.081753,0.133026,0.006584,0.018815,0.019676,-0.030434,-0.002569,-0.001914,-0.015099,0.011474,0.049332,-0.003237,0.021309,0.032779,0.024506,-0.010513,-0.096298,-0.010647,0.003713,-0.058386,-0.031229,-0.036905,-0.088249,-0.062327,0.049001,0.011677,0.074554,0.019880,0.038397,-0.118323,0.033988,-0.053489,0.018765,-0.020725,0.111545,-0.051491,-0.076475,0.019509,0.007766,0.009260,0.044620,0.013179,-0.076218,-0.007256,0.003984,0.047005,0.037081,-0.097244,-0.046197,-0.026379,0.048714,-0.055257,-0.019677,-0.047459,0.012222,0.012510,-0.070430,-0.077746,0.041935,0.008291,-0.082698,-0.031971,0.018252,0.057690,-0.052953,-0.088240,-0.008989,-0.045066,-0.032493,0.024329,0.030256,0.044165,0.062684,-0.023572,0.014322,-0.006493,-0.044392,-0.076273,-0.056699,0.052892,-0.048378,-0.002617,0.101605,-0.062998,0.010276,-0.031381,0.017012,0.042682,-0.028912,-0.001984,0.057112,-0.015472,0.015260,0.004624,-0.023897,0.036997,0.013871,-0.092788,0.073862,0.033584,-0.077469,-0.047053,-0.017948,0.063409,-0.044097,0.047876,-0.108226,-0.056815,0.000000,-0.041540,0.011844,-0.088850,0.052376,0.036445,0.050320,-0.016530,-0.006726,-0.038838,0.083817,0.046651,0.036099,0.001567,0.029542,0.073567,0.063163,0.033818,-0.001224,0.054567,0.045864,0.116669,-0.002458,0.038615,0.029369,0.006031,-0.024741,-0.062473,0.052177,0.078797,-0.011057,-0.051138,-0.058706,0.057061,-0.002965,0.130959,0.076725,-0.037655,-0.018099,-0.001822,0.023973,0.012187,0.028778,0.005247,-0.019862,-0.081722,0.003430,0.006014,0.033833,0.019250,0.093831,0.001819,-0.002761,-0.035058,-0.102622,0.008800,-0.016332,-0.081184,0.044368,-0.082100,-0.009432,0.083410,-0.022066,0.020378,-0.010448,-0