INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-rules-2025-rule-3', 'dpdp-rules-2025', 'The Digital Personal Data Protection Rules, 2025', 'Rule 3', 'Rule 3 — Notice given by Data Fiduciary to Data Principal (Itemised description, links, languages)',
    '3. Notice given by Data Fiduciary to Data Principal. —The notice given by the Data Fiduciary to the 
Data Principal shall— 
(a) be presented and be understandable independently of any other information that has been, is or may 
be made available by such Data Fiduciary; 
(b) give, in clear and plain language, a fair account of the details necessary to enable the Data Principal 
to give specific and informed consent for the processing of her personal data, which shall include, 
at the minimum, — 
(i) an itemised description of such personal data; and 
(ii) the specified purpose or purposes of, and specific description of the goods or services to be 
provided or uses to be enabled by, such processing; and 
(c) give, the particular communication link for accessing the website or app, or both, of such Data 
Fiduciary, and a description of other means, if any, using which such Data Principal may— 

[भाग II—खण् ड 3(i)] 
भारत का रािपत्र : असाधारण  
 
(i) 
withdraw her consent, with the ease of doing so being comparable to that with which 
such consent was given; 
(ii) 
exercise her rights under the Act; and 
(iii) make a complaint to the Board.', 'NOTIFIED_PHASED_18MO', '2027-05-13', 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf', '', '[-0.046339,0.055118,-0.027229,-0.085864,0.009481,-0.013674,0.115802,-0.004798,0.006174,0.045285,0.116397,-0.065399,0.011734,-0.016117,0.024157,0.002537,0.085677,-0.027855,-0.115116,0.041164,0.095198,0.029493,0.028661,0.042051,-0.021583,0.048847,0.016427,-0.018504,0.037368,-0.065107,0.033754,0.065335,-0.004014,0.059325,-0.011672,-0.020532,-0.018368,0.024418,-0.029933,-0.055932,-0.001584,-0.048243,-0.050653,0.024391,-0.016129,0.021869,0.021166,0.045378,-0.076391,-0.004961,-0.069079,0.022642,-0.027998,0.091516,-0.016906,-0.113314,-0.000170,-0.044500,-0.027670,0.075887,-0.080504,0.013519,-0.035508,0.005879,0.070931,-0.014874,-0.024597,-0.026748,-0.012351,0.037536,0.013810,0.000756,-0.058556,0.013867,-0.008704,-0.053658,-0.050151,0.053297,-0.027329,-0.110780,-0.001265,0.077609,0.109850,0.010725,-0.079425,-0.081411,-0.016633,-0.023590,0.015007,-0.049244,0.026793,0.069530,0.037583,0.035003,0.031403,0.002217,-0.048552,-0.076829,0.040308,0.030300,-0.011877,0.064232,-0.125634,0.034709,-0.064031,-0.064416,-0.017772,-0.010001,0.003960,0.031008,-0.058179,-0.026826,-0.051755,-0.012340,-0.002215,0.038467,-0.095736,0.054963,0.050337,-0.071267,-0.016287,0.003400,0.041999,-0.017221,-0.025095,-0.133235,-0.018645,0.000000,0.008307,0.021975,-0.064304,-0.024041,-0.001896,0.016926,-0.022449,-0.029446,0.004234,0.016767,0.030769,-0.005914,0.001309,-0.006260,0.039523,0.038637,0.073526,0.032235,0.105759,0.069075,0.138413,0.048916,0.033121,0.025320,0.043461,-0.031768,-0.028106,0.050483,0.054684,0.017211,-0.002870,-0.032458,0.012117,-0.038191,0.064494,-0.024641,-0.009919,-0.087775,-0.045427,0.023810,0.021154,0.008146,0.007349,-0.022394,-0.049359,0.029744,0.006510,-0.018228,-0.026256,0.076036,-0.013088,0.033837,0.012044,-0.051096,-0.018337,0.035909,-0.047898,-0.023913,-0.009981,-0.012477,-0.020661,-0.068800,-0.027989,0.012035,-0