INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-rules-2025-rule-4', 'dpdp-rules-2025', 'The Digital Personal Data Protection Rules, 2025', 'Rule 4', 'Rule 4 — Registration and obligations of Consent Manager (First Schedule conditions)',
    '4. Registration and obligations of Consent Manager. — (1) A person who fulfils the conditions for 
registration of Consent Managers set out in Part A of First Schedule may apply to the Board for registration 
as a Consent Manager by furnishing such particulars and such other information and documents as the 
Board may publish in this behalf on its website. 
(2) On receipt of such application, the Board may make such inquiry as it may deem fit to satisfy itself 
regarding fulfilment of the conditions set out in Part A of First Schedule, and if it— 
(a) is satisfied, register the applicant as a Consent Manager, under intimation to the applicant, and 
publish on its website the particulars of such Consent Manager; or 
(b) is not satisfied, reject the application and communicate the reasons for the rejection to the 
applicant. 
(3) The Consent Manager shall have obligations as specified in Part B of First Schedule. 
(4) If the Board is of the opinion that a Consent Manager is not adhering to the conditions and obligations 
under this rule,it may, after giving an opportunity of being heard, inform the Consent Manager of such non-
adherence and direct the Consent Manager to take measures to ensure adherence. 
(5) The Board may, if it is satisfied that it is necessary so to do in the interests of Data Principals, after 
giving the Consent Manager an opportunity of being heard, by order, for reasons to be recorded in writing, 
— 
(a) suspend or cancel the registration of such Consent Manager; and 
(b) give such directions as it may deem fit to that Consent Manager, to protect the interests of the Data 
Principals. 
(6) The Board may, for the purposes of this rule, require the Consent Manager to furnish such information 
as the Board may call for.', 'NOTIFIED_PHASED_1YR', '2026-11-13', 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf', '', '[-0.031213,0.012513,-0.047490,0.037372,0.001021,-0.008779,0.053309,0.020495,0.015641,-0.015843,0.024430,-0.099485,0.038221,0.023609,0.068686,-0.020941,0.076262,0.026775,-0.074199,0.023893,0.005085,0.023470,-0.015814,0.032396,-0.162370,-0.041326,0.074337,0.039466,0.059542,0.001933,0.029728,0.040822,0.046181,0.054921,0.032262,-0.067292,-0.057844,-0.069071,-0.036318,-0.017362,0.010787,-0.022380,-0.037477,0.017862,-0.021567,0.041633,0.000098,0.069950,-0.149655,-0.017948,-0.025299,-0.070528,-0.020191,-0.031570,-0.097602,-0.005083,0.044839,-0.067472,-0.020940,-0.009655,-0.037993,-0.020382,-0.085577,0.011206,0.023016,0.056317,-0.047944,0.013577,0.073392,0.035989,-0.025528,-0.048120,-0.061929,0.013028,-0.058534,-0.033290,-0.056018,0.055236,0.073560,-0.128390,-0.028911,0.006666,0.070153,-0.016378,-0.084758,-0.097286,-0.007699,0.070447,0.061994,0.057624,0.101909,0.035813,-0.020856,0.002345,-0.070996,0.046826,-0.034511,0.002263,0.028639,0.016889,-0.016776,0.000057,-0.090887,0.009825,-0.051213,0.019854,-0.032603,-0.054829,0.001725,0.085462,-0.014808,-0.002820,0.070452,-0.013060,0.031590,-0.026443,-0.024889,0.097522,0.036946,-0.057932,-0.022631,0.034682,0.077043,-0.006521,-0.001388,-0.082560,-0.018459,0.000000,-0.052972,-0.016704,-0.092265,0.012817,0.016388,0.045605,0.003925,0.018720,0.034704,0.039934,0.063744,-0.056350,0.017730,-0.072575,-0.044434,0.006080,0.092702,0.117211,-0.020709,0.120076,0.070248,-0.017901,0.039214,0.023037,-0.021569,0.021043,-0.073427,0.036447,0.093891,-0.015790,0.035560,-0.056019,-0.043420,-0.043900,0.088269,0.059540,-0.031317,0.001153,-0.034935,-0.009551,-0.061453,-0.014190,0.002512,0.034405,-0.055043,-0.037199,0.049934,-0.035486,0.044106,0.001747,-0.009711,-0.013435,-0.004367,-0.058373,0.044265,-0.007329,-0.016411,-0.037546,-0.039170,-0.021507,0.063049,-0.006257,-0.127545,0.013168,0.014069,-0.069