INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-rules-2025-rule-5', 'dpdp-rules-2025', 'The Digital Personal Data Protection Rules, 2025', 'Rule 5', 'Rule 5 — Processing of personal data for subsidies, services, licences or certificates',
    '5. Processing of personal data for provision or issue of subsidy, benefit, service, certificate, licence or 
permit by State and its instrumentalities. — (1) Processing the personal data of a Data Principal under 
this rule shall be done following the standards specified in Second Schedule. 
(2) In this rule and the Second Schedule, the reference to any subsidy, benefit, service, certificate, licence 
or permit that is provided or issued— 
(a) under law shall be construed as a reference to provision or issuance of such subsidy, benefit, 
service, certificate, licence or permit in exercise of any power of or the performance of any 
function by the State or any of its instrumentalities under any law for the time being in force; 
(b) under policy shall be construed as a reference to provision or issuance of such subsidy, benefit, 
service, certificate, licence or permit under any policy or instruction issued by the Central 
Government or a State Government in exercise of its executive power; and 
(c) using public funds shall be construed as a reference to provision or issuance of such subsidy, 
benefit, service, certificate, licence or permit by incurring expenditure on the same from, or with 
accrual of receipts to, — 
(i) in case of the Central Government or a State Government, the Consolidated Fund of India 
or the Consolidated Fund of the State or the public account of India or the public 
account of the State; or 
(ii) in case of any local or other authority within the territory of India or under the control of 
the Government of India or of any State, the fund or funds of such authority.', 'NOTIFIED_PHASED_18MO', '2027-05-13', 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf', '', '[-0.077336,0.037163,-0.035132,-0.080770,0.035073,0.035519,0.097024,-0.001827,-0.052481,0.040760,0.088387,-0.005860,0.051843,-0.024459,-0.010266,-0.028674,0.020465,-0.011671,-0.064682,0.052544,0.130507,-0.021236,-0.107673,0.023453,-0.042799,0.016052,-0.009582,-0.025417,0.071071,-0.014937,0.034055,-0.013907,-0.003983,-0.004630,0.052150,0.005084,0.029929,-0.068442,-0.037492,0.024326,0.057362,-0.087131,-0.046505,0.059710,0.036479,0.034927,0.043294,-0.008628,-0.134788,0.024461,-0.076438,0.038474,-0.000776,0.074272,-0.001201,-0.057739,0.012142,-0.002556,-0.027360,0.019158,-0.033865,-0.008219,-0.076091,0.029800,0.002357,-0.019330,-0.005830,-0.014043,-0.010735,0.008585,-0.061942,-0.014059,-0.017885,-0.029674,-0.031277,-0.091590,-0.047205,0.008368,0.031342,-0.161296,0.004067,0.071224,0.051464,-0.053209,-0.001235,-0.045347,-0.051148,-0.021692,0.057606,0.018763,0.032376,-0.018136,0.021363,0.018199,0.046800,0.005192,0.040051,-0.111811,0.054670,0.050284,0.014712,0.051395,-0.078238,0.075162,-0.061054,-0.043481,-0.101725,0.038697,-0.011660,0.021796,-0.035602,0.005674,-0.023751,-0.083418,0.015725,0.032922,-0.070065,0.007511,0.083762,0.010185,-0.033301,0.016554,0.014041,-0.091432,-0.018760,-0.063790,0.009603,0.000000,-0.069970,-0.024988,-0.044403,-0.039742,-0.059536,-0.009069,-0.042593,0.027059,0.004072,0.018831,0.017477,0.084569,-0.028744,0.057855,0.014415,0.053603,0.046027,0.130867,0.092439,0.087934,0.116498,-0.055170,0.032445,0.031546,0.086397,-0.000038,-0.034759,0.005366,0.019737,0.011484,0.126575,0.007345,0.007850,-0.028207,0.051830,0.019962,0.011492,-0.017826,-0.008620,-0.031882,0.061474,0.005039,0.121046,0.063437,-0.064182,-0.033822,0.030648,0.000853,0.051076,0.018110,0.070123,0.019408,-0.054416,-0.111902,0.010210,-0.006762,-0.081263,-0.018339,-0.036600,-0.051039,-0.02