INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-rules-2025-rule-6', 'dpdp-rules-2025', 'The Digital Personal Data Protection Rules, 2025', 'Rule 6', 'Rule 6 — Reasonable security safeguards (Encryption, access control, audit, technical measures)',
    '6. Reasonable security safeguards. — (1) A Data Fiduciary shall protect personal data in its possession or 
under its control, including in respect of any processing undertaken by it or on its behalf by a Data 
Processor, by taking reasonable security safeguards to prevent personal data breach, which shall include, at 
the minimum, — 
(a) appropriate data security measures, such as securing of personal data through encryption, 
obfuscation, masking or the use of virtual tokens mapped to that personal data; 
(b) appropriate measures to control access to the computer resources used by such Data Fiduciary or 
such a Data Processor, wherever applicable; 
(c) visibility on the accessing of such personal data, through appropriate logs, monitoring and review, 
for enabling detection of unauthorised access, its investigation and remediation to prevent 
recurrence; 
(d) reasonable measures for continued processing in the event of confidentiality, integrity or 
availability of such personal data being compromised as a result of destruction or loss of access to 
personal data or otherwise, such as by way of data-backups; 
(e) for enabling the detection of unauthorised access, its investigation, remediation to prevent 
recurrence and continued processing in the event of such a compromise, retain such logs and 
personal data for a period of one year, unless compliance with any law for the time being in force 
requires otherwise; 
(f) appropriate provision in the contract entered into between such Data Fiduciary and such a Data 
Processor, wherever applicable, for taking reasonable security safeguards; and 
(g) appropriate technical and organisational measures to ensure effective observance of security 
safeguards. 
(2) In this rule, the expression “computer resource” shall have the same meaning as is assigned to it in 
Information Technology Act, 2000 (21 of 2000).', 'NOTIFIED_PHASED_18MO', '2027-05-13', 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf', '', '[-0.072184,0.042963,-0.059677,-0.013382,0.027843,0.014316,0.101243,0.019505,0.015586,0.024287,0.060500,0.002668,0.075658,-0.042467,-0.081930,-0.011016,0.018320,0.014797,-0.106324,0.056086,0.025621,-0.027315,-0.031326,0.020181,-0.074950,0.024510,0.018678,-0.048332,-0.029466,-0.023423,-0.003903,-0.027491,0.002377,0.087127,-0.010686,-0.004980,0.039745,-0.020817,-0.010717,-0.054860,-0.093798,-0.080693,-0.061630,0.005911,-0.038954,0.026840,0.032645,0.002505,-0.090078,0.001785,-0.067303,0.059315,-0.046936,0.109017,-0.049442,-0.037293,-0.000122,-0.055610,0.006409,0.049711,0.013700,0.015926,-0.004897,0.000114,0.038143,0.002514,-0.012805,-0.026475,0.059044,0.126132,-0.001877,-0.011836,-0.104537,0.021365,0.048014,-0.035304,-0.114599,-0.052310,-0.004640,-0.071167,0.055361,0.044111,0.078472,-0.012095,-0.024449,0.013291,-0.014089,-0.031542,0.057593,-0.024763,0.008244,0.010118,0.031662,0.050235,0.050989,-0.061925,-0.035165,-0.015115,0.050666,-0.000613,-0.018033,0.037427,-0.060314,0.003749,-0.018201,-0.025698,0.020177,0.008414,0.000199,0.016945,-0.019200,-0.008160,-0.054396,-0.013753,0.042013,0.046532,-0.088109,0.055608,0.019542,0.046566,0.060307,0.021508,0.098194,-0.069864,0.015297,-0.093284,-0.023683,0.000000,-0.038784,0.034414,-0.058973,-0.026042,-0.012309,-0.020145,-0.038144,-0.022803,-0.044058,0.041343,0.040188,0.091391,0.021341,-0.015613,0.094388,0.039189,0.049637,0.067988,0.094940,-0.027026,0.111607,-0.078398,0.049997,0.021898,0.056821,-0.060221,0.002971,0.028368,0.042230,0.029951,-0.035623,0.040644,0.003564,0.016709,0.088048,0.040426,-0.039931,-0.054154,-0.018558,-0.012381,0.008786,0.030721,0.004341,-0.017150,0.007277,-0.051551,-0.047041,0.037297,-0.071722,0.061936,0.006972,0.034066,0.007904,-0.056979,-0.061657,-0.022815,-0.053243,-0.062949,0.011454,0.046058,0.002736,-0.030161,0.020289,-0.024606,-0.103268,-0.036553,0.050541,-0.042319,0.052673,0.005404,-0.092397,-0.021418,0.054119,-0.034511,-0.019484,0.014021,-0.037891,0.035850,-0.063794,-0.064867,-0.028813,-0.009059,0.010642,0.013918,-0.085958,-0.033381,-0.045308,0.011499,-0.050276,-0.009785,0.015971,-0.014174,0.005364,0.010345,-0.039587,-0.000000,-0.044630,-0.053323,-0.062047,0.071210,-0.005007,0.002977,0.000063,-0.016160,0.004602,-0.057627,-0.132514,-0.044042,0.048149,-0.067404,-0.064503,0.041932,-0.003686,-0.026959,-0.108286,-0.002950,-0.030070,0.072292,-0.004997,0.021492,0.028912,0.060321,-0.081121,0.005072,0.085556,0.022604,-0.017002,-0.054055,-0.003739,-0.015556,-0.043037,-0.092158,0.123763,0.024290,0.005261,0.042005,0.063950,0.160106,-0.034918,-0.008828,-0.031473,-0.001769,-0.017290,-0.007654,-0.001157,-0.039513,0.080587,-0.013565,0.069899,0.011471,-0.010288,0.075886,0.102949,0.025074,-0.009699,0.058913,0.027507,-0.065549,0.037149,0.096859,0.031202,-0.012797,-0.007289,0.056964,0.022120,0.015250,0.079803,-0.032286,-0.021067,0.001719,0.046509,-0.060801,-0.001596,-0.071890,-0.099683,0.129826,-0.001656,-0.042927,-0.056602,0.033629,0.038925,-0.141888,0.056919,-0.067861,0.006846,-0.033215,-0.079883,-0.074527,-0.137397,0.028584,0.002276,-0.000000,0.014687,-0.109640,-0.005517,0.057876,0.109604,-0.038506,-0.047560,-0.013320,-0.029692,-0.082340,0.094350,-0.069063,-0.027751,-0.023521,0.048195,-0.036814,0.012897,-0.094516,-0.048951,0.002078,-0.018451,0.008853,-0.107493,0.038704,0.058497,0.026488,0.063235,0.005337,-0.037420,0.046819,-0.034235,-0.002409,0.084014,-0.008839,-0.129492,0.081998,-0.001042,-0.034116,-0.023520,0.047638,0.048885,0.033415,0.033396,0.087215,0.019094,-0.066509,0.031917,-0.000724,-0.021016,-0.009039,-0.045718,-0.002741,0.015700,0.137964,0.018214,0.033467,0.035797,0.045342,0.007839,0.071310,0.081231,0.041995,0.018661,-0.044538]'
