INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-rules-2025-rule-8', 'dpdp-rules-2025', 'The Digital Personal Data Protection Rules, 2025', 'Rule 8', 'Rule 8 — Time period for specified purpose to be deemed as no longer being served (Storage limitation)',
    '8. Time period for specified purpose to be deemed as no longer being served.—(1) A Data Fiduciary, 
who is of such class and is processing personal data for such corresponding purposes as are specified in 
Third Schedule, shall erase such personal data, unless its retention is necessary for compliance with any law 
for the time being in force, or, for the corresponding time period specified in the Third Schedule, if the Data 
Principal neither approaches such Data Fiduciary for the performance of the specified purpose nor exercises 
her rights in relation to such processing. 
(2) At least forty-eight hours before completion of the time period for erasure of personal data under this 
rule, the Data Fiduciary shall inform the Data Principal that such personal data shall be erased upon 
completion of such period, unless she logs into her user account or otherwise initiates contact with the Data 
Fiduciary for the performance of the specified purpose or exercises her rights in relation to the processing 
of such personal data. 
(3) Without prejudice to sub-rules (1) and (2), a Data Fiduciary shall retain, in respect of any processing of 
personal data undertaken by it or on its behalf by a Data Processor, such personal data, associated traffic 
data and other logs of the processing for a minimum period of one year from the date of such processing, 
for the purposes as specified in the Seventh Schedule, after which the Data Fiduciary shall cause such 
personal data and logs to be erased, unless further retention is required for compliance with any other law 
for the time being in force or notified by the Government. 
Illustration. 
Case 1: X, a Data Principal purchases an e-book on an e-book platform Y. Once delivery is 
completed, the specified purpose of processing is served. The platform Y must retain the order details, 
personal data, and logs of the processing (such as order confirmation, payment, and delivery events) for at 
least one year from the date of the transaction, even if X deletes her account. 
Case 2: X, a company engages a cloud service provider C as its Data Processor to host customer 
records. X as the Data Fiduciary, is required to ensure that the C also retains the data and associated logs 
for at least one year before erasure, unless any other applicable law requires a longer period.', 'NOTIFIED_PHASED_18MO', '2027-05-13', 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf', '', '[-0.095927,0.028738,0.025713,-0.025693,-0.006400,-0.045774,0.049084,-0.025993,-0.009973,0.002327,0.081028,0.053387,0.012149,-0.030348,-0.043228,-0.005723,-0.014660,-0.029464,-0.092151,0.051242,0.128465,-0.013739,-0.072405,0.030427,0.002543,0.040563,0.034998,-0.057560,-0.009619,-0.033678,-0.012146,0.010283,0.064397,0.061883,0.008326,-0.011575,-0.007750,0.027446,-0.009600,-0.049371,-0.019107,-0.072862,-0.056610,0.004330,0.000491,0.018501,0.016911,-0.031426,-0.052041,0.050809,-0.045867,0.040664,-0.006314,0.160036,-0.003921,-0.028521,0.012558,0.006381,-0.064577,0.042732,-0.064904,-0.022348,-0.044429,-0.029691,0.088089,-0.012923,-0.013754,-0.062826,0.043481,0.088360,-0.046727,-0.021026,-0.100020,0.057564,0.002196,0.012893,-0.074783,0.009738,-0.001056,-0.079805,0.018613,0.022447,0.025219,-0.037875,-0.051155,-0.084532,-0.019618,0.035513,0.012234,-0.003706,0.037179,0.062660,0.042273,-0.002184,-0.025887,-0.018252,0.004499,0.017346,0.052212,0.036910,-0.025534,0.031400,-0.101740,0.042337,-0.065401,-0.041846,-0.023399,0.072338,-0.062327,0.043671,-0.021510,-0.008358,-0.035001,-0.004895,0.032460,0.093651,-0.087825,0.114939,0.008022,0.036734,0.007762,0.026943,0.052659,-0.025630,-0.017438,-0.054386,0.002067,0.000000,-0.050575,-0.034052,-0.091663,-0.052583,0.018768,-0.006864,-0.031009,-0.003601,0.026299,0.014608,0.021876,0.036635,-0.017617,-0.052411,-0.005890,0.047678,0.084741,0.061960,0.097656,-0.000351,0.190024,-0.023077,0.040896,0.049737,0.038106,-0.052544,-0.001302,0.003299,-0.018586,0.013103,0.003850,0.052387,0.005333,0.015273,0.074717,0.031028,0.062399,-0.055955,0.011183,0.026985,0.083920,0.046154,0.027807,-0.011786,-0.064089,-0.088081,0.054484,0.052171,-0.054729,0.114898,0.056467,0.034367,0.015263,-0.103827,-0.059398,0.035929,-0.003574,-0.089062,-0.00