INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-rules-2025-rule-13', 'dpdp-rules-2025', 'The Digital Personal Data Protection Rules, 2025', 'Rule 13', 'Rule 13 — Additional obligations of Significant Data Fiduciary (DPIA, audit, DPO requirements)',
    '13. Additional obligations of Significant Data Fiduciary. — (1) A Significant Data Fiduciary shall, once 
in every period of twelve months from the date on which it is notified as such or is included in the class of 
Data Fiduciaries notified as such, undertake a Data Protection Impact Assessment and an audit to ensure 
effective observance of the provisions of this Act and the rules made thereunder. 
(2) A Significant Data Fiduciary shall cause the person carrying out the Data Protection Impact Assessment 
and audit to furnish to the Board a report containing significant observations in the Data Protection Impact 
Assessment and audit. 
(3) A Significant Data Fiduciary shall observe due diligence to verify that technical measures including 
algorithmic software adopted by it for hosting, display, uploading, modification, publishing, transmission, 
storage, updating or sharing of personal data processed by it are not likely to pose a risk to the rights of 
Data Principals. 
(4) A Significant Data Fiduciary shall undertake measures to ensure that personal data specified by the 
Central Government, on the basis of the recommendations of a committee constituted by it, is processed 
subject to the restriction that the personal data and the traffic data pertaining to its flow is not transferred 
outside the territory of India. 
(5) In this rule, “committee” means a committee constituted by the Central Government for the purpose of 
this rule, which shall include officials from the Ministry of Electronics and Technology and may include 
officials from other Ministries or Department of the Central Government.', 'NOTIFIED_PHASED_18MO', '2027-05-13', 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf', '', '[-0.034437,0.030911,0.009781,-0.030904,0.014693,0.004642,0.063013,0.029593,-0.050480,0.036763,0.032074,-0.027341,0.036679,-0.027733,-0.072102,-0.003987,0.033946,-0.028266,-0.084742,0.068885,0.055696,-0.017571,-0.022566,0.026503,-0.029683,0.014761,-0.023055,-0.018876,-0.012496,-0.070930,-0.013943,0.010345,0.077970,0.085456,-0.029350,-0.027381,0.027932,0.002960,-0.009286,-0.049509,-0.039037,-0.074652,-0.012649,-0.010009,-0.033611,-0.016927,0.077474,-0.011772,-0.086046,0.093342,-0.095697,0.036940,0.002820,0.129529,-0.023231,-0.104392,0.022275,-0.076286,-0.046754,0.033124,-0.047543,-0.013181,-0.043014,0.000026,0.064219,0.005953,-0.034443,-0.040106,-0.008780,0.053100,-0.015794,-0.040324,-0.048609,0.047738,0.028036,-0.036114,-0.116344,0.046903,0.034194,-0.123350,0.025356,0.059055,0.035519,-0.006110,-0.025217,-0.076611,0.047046,0.004713,-0.071091,-0.003890,0.066467,0.041913,0.029173,0.048994,0.009348,-0.014349,-0.070284,-0.080433,0.089023,0.017935,0.031756,0.047671,-0.051835,0.038653,-0.058041,-0.057473,0.011262,-0.028392,-0.029756,0.045979,-0.023367,0.018770,-0.072994,-0.096495,0.025857,-0.006900,-0.112946,0.097569,-0.000822,-0.013769,0.034695,-0.010580,0.080688,-0.044927,0.039264,-0.056330,-0.024465,0.000000,0.010818,0.010943,-0.065919,-0.025682,-0.019427,-0.024299,-0.047503,-0.017755,-0.053241,0.003588,0.010062,0.098334,0.018195,-0.011315,0.068708,0.070821,0.032423,0.029242,0.115978,0.012826,0.149181,-0.087945,0.055678,0.070956,0.083979,-0.035480,-0.018210,0.063518,-0.016903,0.048403,-0.006023,-0.033525,0.062860,0.004277,0.075394,0.036754,-0.066738,-0.068546,0.005724,0.051510,0.055165,0.023341,-0.018737,0.007050,-0.047588,-0.015029,0.018886,0.058074,-0.018026,0.036348,0.041692,-0.015564,0.033330,-0.044306,-0.024808,0.038702,-0.030584,-0.103898,0.040231,-0.007593,-0.01