INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-rules-2025-rule-14', 'dpdp-rules-2025', 'The Digital Personal Data Protection Rules, 2025', 'Rule 14', 'Rule 14 — Rights of Data Principals (Access, Correction, Erasure, Grievance Redressal, Nomination)',
    '14. Rights of Data Principals. — (1) For enabling Data Principals to exercise their rights under the Act, 
the Data Fiduciary and, where applicable, the Consent Manager, shall prominently publish on its website or 
app, or both, as the case may be, — 

 
(a) the details of the means using which a Data Principal may make a request for the exercise of such 
rights; and 
(b) the particulars, if any, such as the username or other identifier of such a Data Principal, which may 
be required to identify her under its terms of service. 
(2) To exercise the rights of the Data Principal under the Act, she may make a request to the Data Fiduciary 
to whom she has previously given consent for processing of her personal data, using the means and 
furnishing the particulars required by such Data Fiduciary for the exercise of such rights. 
(3) Every Data Fiduciary and Consent Manager shall prominently publish on its website or app, or both, as 
the case may be, within a reasonable period not exceeding ninety days under its grievance redressal system 
for responding to the grievances of Data Principals and shall, for ensuring the effectiveness of the system in 
responding within such period, implement appropriate technical and organisational measures. 
(4) To exercise the rights of the Data Principal under the Act, she may, in accordance with the terms of 
service of the Data Fiduciary and such law as may be applicable, nominate one or more individuals, using 
the means and furnishing the particulars required by such Data Fiduciary for the exercise of such right.  
(5) In this rule, the expression “identifier” shall mean any sequence of characters issued by the Data 
Fiduciary to identify the Data Principal and includes a customer identification file number, customer 
acquisition form number, application reference number, enrolment ID, email address, mobile number or 
licence number that enables such identification.', 'NOTIFIED_PHASED_18MO', '2027-05-13', 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf', '', '[-0.066480,0.037131,-0.023775,-0.025540,-0.034031,-0.019923,0.042888,0.023566,-0.039696,0.032987,0.088767,-0.009171,0.062239,-0.025526,0.006909,0.032173,0.068075,-0.036054,-0.145703,0.060178,0.050343,0.020063,-0.024491,0.041314,-0.045460,0.029622,0.020185,-0.070427,-0.003502,-0.022832,-0.028933,-0.015063,0.040797,0.119174,0.033785,-0.046845,-0.010775,-0.002261,-0.059988,-0.003660,-0.035029,-0.053347,-0.026015,0.043321,-0.031511,0.011563,0.079652,0.009161,-0.075431,0.051922,-0.042339,0.008230,0.017655,0.118030,-0.069498,-0.055348,0.029061,-0.032101,-0.020502,0.050480,-0.057363,-0.016251,-0.055968,-0.011407,0.016970,-0.009345,-0.013903,-0.030870,0.015505,0.034064,0.010974,-0.017445,-0.040737,0.049397,0.014822,-0.043928,-0.105042,0.038077,0.051270,-0.115293,0.048227,0.075843,0.054667,0.053846,-0.045833,-0.068827,-0.005220,0.040405,-0.011129,-0.005374,0.047685,0.044601,0.049435,0.008842,-0.025871,-0.001795,-0.063408,-0.082706,0.046828,0.003905,-0.036412,0.060049,-0.058483,0.012944,-0.034203,-0.082410,-0.016479,-0.005062,-0.029667,0.080033,-0.028031,-0.008664,-0.041329,-0.046365,0.033634,-0.029873,-0.132767,0.064214,-0.018729,-0.071057,0.028377,0.007519,0.019075,-0.011451,0.054798,-0.063159,-0.066751,0.000000,0.005371,0.026514,-0.011038,0.006152,0.032767,0.013162,-0.040154,-0.013229,-0.006845,0.044158,0.015925,0.073648,0.024661,-0.075944,-0.002991,0.076081,0.099174,0.067923,0.072395,0.054307,0.118131,-0.005146,0.055485,0.032206,0.016443,-0.009686,-0.063385,0.048579,0.054464,-0.003005,-0.004902,-0.036739,0.041840,0.020097,0.093336,-0.002015,0.055003,-0.049674,0.023396,0.054372,0.078305,0.010917,0.039792,0.014212,-0.054022,0.013989,0.049201,0.002229,0.015239,0.068128,0.026338,0.028736,-0.021319,-0.037185,0.025482,0.014126,-0.043788,-0.075306,0.020654,-0.062365,0.027560,-0.025668,0.002602,-0.003