) VALUES (
    'dpdp-rules-2025-rule-17', 'dpdp-rules-2025', 'The Digital Personal Data Protection Rules, 2025', 'Rule 17', 'Rule 17 — Appointment of Chairperson and other Members of the Board (Search-cum-Selection)',
    '17.Appointment of Chairperson and other Members.— (1) The Central Government shall constitute a 
Search-cum-Selection Committee, with the Cabinet Secretary as the chairperson and the Secretaries to the 
Government of India in charge of the Department of Legal Affairs and the Ministry of Electronics and 
Information Technology and two experts of repute having special knowledge or practical experience in a 
field which in the opinion of the Central Government may be useful to the Board as members, to 
recommend individuals for appointment as Chairperson. 
(2) The Central Government shall constitute a Search-cum-Selection Committee, with the Secretary to the 
Government of India in the Ministry of Electronics and Information Technology as the chairperson and the 
Secretary to the Government of India in charge of the Department of Legal Affairs, and two experts of 
repute having special knowledge or practical experience in a field which in the opinion of the Central 
Government may be useful to the Board as members, to recommend individuals for appointment as a 
Member other than the Chairperson.  
(3) The Central Government shall, after considering the suitability of individuals recommended by the 
Search-cum-Selection Committee, appoint the Chairperson or other Member, as the case may be. 
(4) No act or proceeding of the Search-cum-Selection Committee specified in sub-rules (1) and (2) of this 
rule shall be called in question on the ground merely of the existence of any vacancy or absences in such 
committee or defect in its constitution.', 'IN_FORCE', '2025-11-13', 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf', '', '[-0.068246,-0.028213,-0.018480,-0.037256,-0.030555,0.013805,0.055328,0.055050,0.009969,0.006040,-0.028574,-0.056461,0.066556,-0.020743,-0.001224,-0.029859,0.047357,-0.019029,-0.004437,-0.019404,0.012636,-0.012100,-0.032337,-0.129272,-0.109213,-0.096349,-0.034837,-0.062958,0.011539,-0.025902,0.007487,0.087503,0.034277,0.055582,-0.016441,0.021309,-0.053906,0.004927,0.076965,-0.036364,0.002726,0.007831,-0.047605,-0.043138,0.042683,0.018498,0.026096,0.020052,-0.070060,-0.053882,-0.087175,-0.072838,-0.012025,0.032190,-0.026504,-0.039994,0.003535,-0.110767,0.018589,-0.022672,0.009008,-0.006371,-0.071101,-0.008973,0.057829,-0.044224,0.041365,-0.056735,0.056602,-0.017176,0.026244,0.009787,-0.057709,0.050422,-0.075863,-0.012557,0.006203,0.062147,0.058736,-0.094252,0.020043,0.121477,0.038009,-0.007354,0.002564,-0.019206,-0.034590,-0.033860,-0.033440,-0.022644,0.090835,0.017687,0.043567,-0.009283,0.031851,0.025999,0.035232,0.019547,0.058333,0.030378,-0.007241,0.031192,-0.053905,0.020412,-0.174641,0.007131,-0.052454,-0.023228,0.076639,-0.033453,-0.120284,0.034224,-0.015889,-0.072477,-0.041781,0.025433,-0.026874,0.129189,0.017447,-0.013035,-0.050937,0.047410,0.014205,-0.107665,0.030243,-0.054839,-0.031195,-0.000000,-0.030456,0.047236,-0.008427,-0.030320,-0.035634,0.000348,0.014115,0.009889,-0.000419,0.027363,-0.050163,-0.047385,0.032557,-0.045213,0.010355,0.009773,0.032571,0.006249,-0.056538,0.035445,0.049161,0.005613,0.022093,0.009044,0.056384,0.015094,0.063668,0.007033,0.047273,0.030170,0.030623,0.003479,-0.063165,0.054651,0.063053,0.004030,-0.007352,0.009298,0.059504,-0.017948,-0.073486,0.053880,0.059470,0.003396,-0.034501,0.000310,0.032965,0.064632,0.029342,0.059699,-0.038494,0.001113,0.062981,-0.019618,0.053933,0.066377,0.039789,0.022985,0.031572,0.036686,0.014004,0.004498,-0.066058,0.064525,-0.052455,-0.034716,0.0