INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-rules-2025-rule-21', 'dpdp-rules-2025', 'The Digital Personal Data Protection Rules, 2025', 'Rule 21', 'Rule 21 — Terms and conditions of appointment of officers and employees of Board',
    '21. Terms and conditions of appointment and service of officers and employees of Board.— (1) The 
Board may, with previous approval of the Central Government, appoint such officers and employees as it 
may deem necessary for the efficient discharge of its functions under the provisions of the Act. 
(2) The terms and conditions of service of officers and employees of the Board shall be such as are 
specified in Sixth Schedule.', 'IN_FORCE', '2025-11-13', 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf', '', '[-0.038822,-0.002601,0.042253,-0.026087,-0.076792,0.052086,0.030744,-0.033540,-0.019256,-0.006773,0.016357,0.020627,-0.040928,0.011457,-0.025733,-0.035008,0.076499,-0.011991,-0.025065,0.069120,0.064478,-0.027106,-0.095183,0.007950,-0.085653,-0.101362,-0.014099,0.001235,0.006279,-0.029048,0.056017,0.020495,0.097654,0.036531,0.044316,0.003533,-0.016781,-0.064026,0.044699,0.002586,0.020704,-0.045065,-0.022326,0.056799,-0.011126,0.053929,0.008065,-0.040922,-0.074647,-0.001702,-0.014823,-0.075869,-0.005477,-0.003016,-0.064423,-0.061191,-0.010330,-0.130755,0.039147,-0.003425,-0.085333,-0.007524,0.004203,0.072289,0.039630,-0.018074,-0.060205,-0.083090,-0.009474,-0.016646,-0.056950,-0.035535,-0.058204,0.022527,-0.070168,0.041251,0.006168,0.054928,0.054854,-0.146943,-0.047350,-0.000304,0.031296,-0.009852,-0.010405,-0.022074,-0.037245,-0.010178,-0.005511,0.052403,0.144526,0.038423,0.054294,-0.031662,-0.018021,-0.003645,0.018692,-0.017736,0.012261,0.032974,0.005239,-0.010786,-0.017373,0.001587,-0.138825,-0.025121,-0.029096,-0.070724,-0.026508,-0.016214,-0.074358,-0.004514,0.002098,-0.044755,-0.003969,0.036004,-0.014983,0.049898,0.039173,-0.075294,0.038103,0.064852,0.043647,-0.023816,-0.036504,0.012642,0.073749,-0.000000,-0.047769,-0.031337,-0.058708,-0.029197,0.031433,-0.029922,-0.030320,-0.042494,0.013118,0.058536,-0.045191,0.036855,0.067549,-0.094399,0.025477,0.032537,0.071490,0.074831,0.044860,0.094754,0.063946,-0.053265,0.013134,0.089721,0.101324,0.016203,-0.026502,-0.003502,0.052441,0.013628,0.050533,-0.011028,0.014304,0.002271,0.047217,0.057596,0.006811,0.039208,0.024135,-0.056093,-0.011267,-0.011758,0.004851,0.051317,0.020581,-0.060396,0.037189,0.071719,0.038559,0.045370,-0.010464,-0.057487,0.063173,-0.018713,0.125946,0.036789,-0.011957,0.084390,0.009553,-0.017194,0.055854,0.019422,-0.046132,0.064022,-0.000909,-0.059244,-0