INSERT INTO public."Legal_Chunks" (
    id, document_id, document_title, section_num, section_title,
    chunk_text, commencement_status, enforceable_date, source_url, sha256, embedding
) VALUES (
    'dpdp-rules-2025-rule-22', 'dpdp-rules-2025', 'The Digital Personal Data Protection Rules, 2025', 'Rule 22', 'Rule 22 — Appeal to Appellate Tribunal (Form, fee, and manner of electronic filing)',
    '22. Appeal to Appellate Tribunal. — (1) Any person aggrieved by an order or direction of the Board, 
may prefer an appeal before the Appellate Tribunal, it shall be filed in digital form as the Appellate 
Tribunal may decide. 
(2) An appeal filed with the Appellate Tribunal shall be accompanied by fee of like amount as is applicable 
in respect of an appeal filed under the Telecom Regulatory Authority of India Act, 1997 (24 of 1997), 
unless reduced or waived by the Chairperson of the Appellate Tribunal at her discretion, and the same shall 
be payable digitally using the Unified Payments Interface or such other payment system authorised by the 
Reserve Bank of India. 
(3) The Appellate Tribunal—  
(a) shall not be bound by the procedure laid down by the Code of Civil Procedure, 1908 (5 of 1908), 
but shall be guided by the principles of natural justice and, subject to the provisions of the Act, may 
regulate its own procedure; and 
(b) shall function as a digital office which, without prejudice to its power to summon and enforce the 
attendance of any person and examine her on oath, may adopt techno-legal measures to conduct 
proceedings in a manner that does not require physical presence of any individual.', 'NOTIFIED_PHASED_18MO', '2027-05-13', 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf', '', '[-0.072726,0.061658,-0.070843,-0.117458,-0.076233,0.002356,0.083288,0.078114,0.008644,0.073374,0.020291,-0.017570,0.022105,0.035863,0.004498,-0.025391,0.040593,-0.021286,0.050898,0.077179,0.105724,0.037610,-0.075041,-0.074791,-0.009507,-0.096698,-0.051736,-0.077756,0.020428,-0.016624,-0.040765,0.088526,-0.010721,0.022627,-0.015519,-0.064405,0.035975,-0.004756,-0.046593,-0.060216,0.028076,-0.037962,-0.006845,-0.051172,0.038638,0.008573,0.021453,0.001147,-0.126049,-0.045732,-0.068192,-0.046281,-0.001283,0.072516,-0.061995,-0.094025,0.098760,-0.024899,0.034804,-0.017917,0.009571,0.004150,-0.016339,0.030204,0.004247,0.056279,0.039314,-0.038569,0.064507,-0.009196,0.021009,0.005252,0.012946,-0.000028,-0.109190,-0.000434,0.000345,0.073747,0.015761,-0.021227,-0.007848,-0.061796,0.062286,-0.037065,-0.042737,0.013268,-0.009367,0.036181,0.039884,-0.017020,0.123034,0.083591,0.006896,0.016458,0.022480,-0.103223,0.021702,-0.047565,0.085348,0.053141,0.043066,0.108180,-0.071680,0.013042,-0.054904,0.013807,0.006133,-0.054801,0.064427,-0.073399,-0.104844,-0.008923,0.044572,-0.050939,-0.049407,0.052141,0.019458,0.066107,0.070704,-0.017890,-0.020763,0.064288,-0.100523,-0.039988,0.076703,0.013713,0.020344,0.000000,-0.045997,0.014839,-0.075882,-0.048963,-0.037593,0.008620,0.036658,0.035376,0.000263,-0.002669,-0.059296,-0.017571,0.055450,-0.031503,0.005780,0.010384,-0.038148,-0.023687,0.078286,0.019165,0.044592,-0.096792,0.015237,0.069207,-0.046986,-0.046467,-0.001624,-0.025600,0.035339,0.000698,0.000754,-0.035495,0.076824,0.050170,0.061226,0.044607,0.030916,0.028155,0.028766,0.011858,-0.042040,0.018191,0.014615,-0.023340,-0.022826,-0.051971,-0.010249,0.038454,0.014563,0.084395,0.006048,0.026297,0.012222,-0.001661,-0.003813,0.006384,-0.054703,-0.036973,0.006661,0.033165,0.0150