) VALUES (
    'dpdp-rules-2025-rule-23', 'dpdp-rules-2025', 'The Digital Personal Data Protection Rules, 2025', 'Rule 23', 'Rule 23 — Calling for information from Data Fiduciary or intermediary',
    '23. Calling for information from Data Fiduciary or intermediary. — (1) The Central Government may, 
for such purposes of the Act as are specified in Seventh Schedule, acting through the corresponding 
authorised person specified in the said Schedule, require any Data Fiduciary or intermediary to furnish such 
information as may be called for, within the specified period as may be given in such. 
(2) Where the disclosure of furnishing of information as referred to in sub-rule (1) is likely to prejudicially 
affect the sovereignty and integrity of India or security of the State, the Central Government may require 
the Data Fiduciary or intermediary to not disclose such furnishing to affected Data Principal or any other 
person except with the previous permission, in writing, of the authorised person.  
(3) For the purposes of this rule, the expression “intermediary” shall have the same meaning as assigned to 
it in the Information Technology Act, 2000 (21 of 2000).', 'NOTIFIED_PHASED_18MO', '2027-05-13', 'https://www.meity.gov.in/static/uploads/2025/11/53450e6e5dc0bfa85ebd78686cadad39.pdf', '', '[-0.075229,0.004576,0.003285,-0.056200,-0.001201,-0.034712,0.077345,0.015340,-0.031486,-0.029400,0.035490,0.005657,0.054075,0.029272,0.002157,0.013428,0.029390,-0.023989,-0.098991,0.064127,0.145684,0.051711,-0.051144,-0.002206,-0.017360,-0.033337,0.019607,-0.084399,0.025355,-0.021019,0.005672,0.019664,0.043628,0.078609,-0.013020,-0.019112,0.009952,-0.012505,0.025896,-0.043781,0.031359,-0.048838,-0.019105,-0.008250,-0.021722,0.013424,0.047810,-0.024930,-0.113961,0.028127,-0.106909,0.015488,-0.041264,0.134972,-0.044880,-0.100210,0.013753,-0.027240,-0.028400,0.057073,-0.030975,-0.019740,-0.008371,0.012408,0.087642,-0.010292,0.016849,0.009449,-0.016152,0.036046,0.003600,-0.015025,-0.024776,0.028147,-0.027916,-0.033608,-0.081550,0.066213,-0.025382,-0.136104,0.029438,0.050712,0.085296,0.011072,-0.050388,-0.061685,-0.011968,-0.027218,0.001348,-0.002170,0.049517,0.010302,0.050209,0.026464,-0.013933,-0.059322,-0.019942,-0.066660,0.051600,0.020953,-0.051040,0.045331,-0.102085,0.037420,-0.093874,-0.083990,-0.020045,-0.000859,-0.057454,0.039072,-0.065260,0.065680,-0.041453,-0.078552,0.001165,0.006138,-0.069062,0.098005,0.057161,-0.076634,-0.030487,0.049352,0.031901,-0.015550,-0.030010,-0.087109,-0.034382,0.000000,-0.039785,-0.012928,-0.000725,-0.009838,-0.021853,-0.037172,-0.054882,-0.057018,-0.004239,0.037048,0.033672,0.031330,0.042409,-0.072702,-0.012034,0.101825,0.043042,0.050113,0.124458,0.042430,0.123618,-0.012599,0.043197,0.038175,0.044499,-0.017754,-0.014323,-0.017832,0.063369,0.023454,0.049336,-0.012389,0.074680,-0.003121,0.097313,0.046704,0.022919,-0.063105,0.004469,0.023667,0.064179,0.014955,0.021227,-0.032574,-0.010387,-0.006490,0.003358,0.078980,-0.038018,0.098724,0.006257,0.065501,0.016989,-0.074721,0.026433,-0.009899,-0.006605,-0.076435,0.023272,-0.035273,0.007813,-0.081369,-0.